INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the Prosecutor General''s Office (PGR), Rural and BMG passed R$ 55 million in simulated loans to Valério''s group; Rural''s executives were convicted of fraudulent management and laundering, and some defendants argued that the money went to campaign debts.', NULL, 'Total passed on by Rural and BMG according to the PGR; BMG is not a node in this case', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_banco_rural' AND target = 'esquema_mensalao' AND type = 'transaction' AND status = 'confirmed' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
