INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'It operated as an omnibus account in New York, pooling sub-accounts used to send money abroad; it was shut down by order of a US court and its databases fed the CPMI and Operation Farol da Colina.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_beacon_hill' AND target = 'esquema_banestado' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
