INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'It granted the STN consortium, using FNE funds and after changing internal rules to fit the operation, financing approved on 25 June 2004; the MPF maintains that the bribe came from it, the TCU found it lawful and the 2012 judgment found a breach of impersonality but no proof of an improper advantage.', NULL, 'Amount of the financing to the STN according to the MPF petition (R$ 299,995,032.33), which the press rounds to R$ 300 million; it is not the amount of the alleged bribe', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_bnb' AND target = 'esquema_dolares_na_cueca' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
