INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Chocolate shop identified by the Rio de Janeiro State Prosecution Service (MP-RJ) as a means of laundering cash from the rachadinhas; the indictment that cited it was rejected by the Rio de Janeiro Court of Justice (TJ-RJ) in 2022. Flávio Bolsonaro says the shop''s transactions are regular.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_bolsotini_chocolates' AND target = 'esquema_caso_queiroz_rachadinhas' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2019 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
