INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Its chairman, Luiz Carlos Trabuco, was charged in 2016, with nine others, over alleged involvement in fraud at the tax appeals board (Carf) in the bank''s favour; in June 2017 the 4th Panel of the Federal Regional Court of the 1st Region (TRF-1) closed the criminal case against Trabuco, at the defence''s request, finding no evidence of his participation. The outcome for the other nine people charged was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_bradesco' AND target = 'esquema_operacao_zelotes' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2016 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Su presidente, Luiz Carlos Trabuco, fue acusado en 2016, junto con otras nueve personas, de supuesta implicación en fraudes en el Carf (tribunal administrativo fiscal) a favor del banco; en junio de 2017 la Sala 4.ª del Tribunal Regional Federal de la 1.ª Región (TRF-1) archivó el proceso penal contra Trabuco, a petición de la defensa, al entender que no había pruebas de su participación. No se ha localizado el desenlace para los demás acusados.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_bradesco' AND target = 'esquema_operacao_zelotes' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2016 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
