INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Public bank that bought credit portfolios from Master in which the Federal Police identifies at least R$ 12 billion in fraudulent assets, in purchases that, according to the Federal Police, sidestepped governance mechanisms. The former BRB president''s defence says that, of a R$ 12.2 billion portfolio, R$ 10.5 billion was replaced with sound assets and that decisions were taken collectively.', NULL, 'Minimum of assets passed on fraudulently according to the Federal Police; the report records a minimum loss of R$ 2.7 billion to BRB', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_brb' AND target = 'esquema_banco_master_inss' AND type = 'transaction' AND status = 'confirmed' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Banco público que compró al Master carteras de crédito en las que la Policía Federal señala al menos 12.000 millones de reales en activos fraudulentos, en compras que, según la Policía Federal, eludieron mecanismos de gobernanza. La defensa del expresidente del BRB afirma que, de una cartera de 12.200 millones de reales, 10.500 millones se sustituyeron por activos sólidos y que las decisiones eran colegiadas.', NULL, 'Mínimo de activos transferidos de forma fraudulenta según la Policía Federal; el informe registra un perjuicio mínimo de 2.700 millones de reales al BRB', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_brb' AND target = 'esquema_banco_master_inss' AND type = 'transaction' AND status = 'confirmed' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
