INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Service provider to the Federal District government convicted of administrative misconduct (improbidade administrativa) in civil proceedings, together with José Roberto Arruda, José Geraldo Maciel and José Celso Valadares Gontijo, on the Federal District Public Prosecution Service (MPDFT) allegation that payments under its contracts funded bribes; in June 2026 the 6th Civil Panel of the Federal District Court of Justice (TJDFT) unanimously upheld the conviction and set R$ 1 million per defendant in collective moral damages. Arruda''s defence says the evidence was declared unlawful by the Electoral Courts; no final (unappealable) judgment was located.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_call_tecnologia' AND target = 'esquema_caixa_pandora' AND type = 'contract' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
