INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Hired by the STN to draw up the financing project, it allegedly received about R$ 1.97 million against R$ 20,000 provided for in the project, which the MPF saw as a possible vehicle for improper advantages. The company says it was a regular advisory contract; the 2012 judgment dismissed the claim against it and the MPF itself asked for its acquittal.', NULL, 'Amount identified by the BNB''s internal inquiry according to the MPF petition; the company reports R$ 1,970,817.36 received under a technical advisory contract', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_enphase' AND target = 'esquema_dolares_na_cueca' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
