INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In January 2026 it was withholding about R$ 2 billion relating to roughly 254,000 Master payroll-loan contracts under review for flaws such as missing interest-rate information and problems validating electronic signatures; since September 2025 the bank has been unable to grant new payroll loans because its cooperation agreement was not renewed. Vorcaro''s defence says the bank always acted in strict compliance with INSS rules.', NULL, 'Approximate amount withheld by the INSS in January 2026', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_inss' AND target = 'esquema_banco_master_inss' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En enero de 2026 retenía cerca de 2.000 millones de reales correspondientes a unos 254.000 contratos de préstamos con descuento en nómina del Master, en revisión por fallos como la falta de información sobre los intereses y problemas en la validación de firmas electrónicas; desde septiembre de 2025 el banco no concede nuevos préstamos de este tipo porque el acuerdo de cooperación no se renovó. La defensa de Vorcaro afirma que el banco siempre actuó en estricto cumplimiento de las normas del INSS.', NULL, 'Importe aproximado retenido por el INSS en enero de 2026', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_inss' AND target = 'esquema_banco_master_inss' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
