INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Body harmed by the fraud in supply tenders; the MPF prosecutor Marlon Weichert estimated in December 2004 a loss of US$ 100 million in blood products, while the ministry''s own estimate of R$ 2 billion over 13 years was not confirmed by the Federal Police in the first inquiry.', NULL, 'Estimate by the prosecutor Marlon Weichert, with a conversion of about R$ 280 million given by the source; the ministry estimated R$ 2 billion over 13 years, not confirmed by the Federal Police in June 2004', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_ministerio_saude' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Órgano perjudicado por los fraudes en licitaciones de suministros; el fiscal del MPF Marlon Weichert estimó en diciembre de 2004 una pérdida de 100 millones de dólares en hemoderivados, mientras que la estimación del propio ministerio, de 2.000 millones de reales en 13 años, no fue confirmada por la Policía Federal en la primera investigación.', NULL, 'Estimación del fiscal Marlon Weichert, con una conversión de unos 280 millones de reales dada por la fuente; el ministerio estimó 2.000 millones de reales en 13 años, no confirmados por la Policía Federal en junio de 2004', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_ministerio_saude' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Car maker that, according to the prosecution, hired lobbying services worth R$ 32 million, together with CAOA, to secure provisional measures; in April 2020 the 4th Panel of the Federal Regional Court of the 1st Region (TRF-1) acquitted the nine defendants in that case, including the lobbyists hired, of corruption, money laundering and criminal association; former Senate director Fernando Mesquita was convicted of improperly using his office (advocacia administrativa).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_mmc_mitsubishi' AND target = 'esquema_operacao_zelotes' AND type = 'contract' AND status = 'acquitted' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Fabricante de automóviles que, según la acusación, habría contratado junto con CAOA servicios de presión por 32 millones de reales para la aprobación de medidas provisionales; en abril de 2020 la Sala 4.ª del Tribunal Regional Federal de la 1.ª Región (TRF-1) absolvió a los nueve acusados de ese proceso, incluidos los lobistas contratados, de cohecho, blanqueo de capitales y asociación criminal; el exdirector del Senado Fernando Mesquita fue condenado por patrocinio de intereses privados ante la Administración (advocacia administrativa).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_mmc_mitsubishi' AND target = 'esquema_operacao_zelotes' AND type = 'contract' AND status = 'acquitted' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
