INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Vedoin family company identified by the Federal Prosecution Service (MPF) and the Federal Police as the centre of the scheme: it won rigged tenders to sell ambulances and medical equipment to municipalities and paid bribes to legislators in exchange for amendments. The company and its owners face hundreds of criminal and administrative misconduct cases.', NULL, 'Estimate made at the time of the operation for the total moved by the group; the Office of the Comptroller General (CGU) and Denasus established a minimum loss of R$ 15.5 million; the partial CPI report counted R$ 9.46 million in bribes; the CPI''s final report speaks of more than R$ 100 million diverted.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'emp_planam' AND target = 'esquema_sanguessugas' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
