INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Black-market currency dealer identified as the linchpin of the operation and a cooperating witness. In July 2025 Justice Dias Toffoli declared null all Lava Jato acts against him, finding that there had been collusion between the then judge Sergio Moro, the MPF and the Federal Police to pressure him to cooperate; the plea agreement was upheld. Moro called the decision an "inversion of values".', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_alberto_youssef' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Cambista del mercado negro señalado como pieza central de la operación y delator. En julio de 2025 el ministro Dias Toffoli declaró la nulidad de todos los actos de la Lava Jato contra él, al entender que hubo connivencia entre el entonces juez Sergio Moro, el MPF y la Policía Federal para presionarlo a colaborar; el acuerdo de colaboración se mantuvo. Moro calificó la decisión de «inversión de valores».', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_alberto_youssef' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
