INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police in October 2026, described as part of the executive and financial core of the dealings with BRB. His defence did not comment on the decision and has said on other occasions that the transactions under investigation took place after he left Master in May 2024.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_augusto_lima' AND target = 'esquema_banco_master_inss' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal en octubre de 2026, señalado como integrante del núcleo ejecutivo-financiero de las operaciones con el BRB. Su defensa no se pronunció sobre la imputación y ha afirmado en otras ocasiones que las operaciones investigadas son posteriores a su salida del Master, en mayo de 2024.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_augusto_lima' AND target = 'esquema_banco_master_inss' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
