INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He took part in the meetings with Gtech executives in 2003 and is a defendant in the criminal case before the 10th Federal Court; according to the MPF, the planned bribe payments did not take place. G1 noted that it was awaiting a response from Cachoeira''s defence, whose position was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'emp_gtech' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Participó en las reuniones con directivos de Gtech en 2003 y es acusado en la causa penal del Juzgado Federal 10.º; según el MPF, los pagos de soborno previstos no se produjeron. G1 registró que esperaba respuesta de la defensa de Cachoeira, cuya postura no se localizó.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'emp_gtech' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In April 2013, the TJ-RJ reduced the sentence to 6 years and 8 months'' imprisonment and acquitted him of tender fraud; the rapporteur considered that Cachoeira recorded the conversation because he felt Waldomiro was demanding too much.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2013 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En abril de 2013, el TJ-RJ redujo la pena a 6 años y 8 meses de reclusión y lo absolvió del fraude en la licitación; el ponente consideró que Cachoeira grabó la conversación por entender que Waldomiro exigía demasiado.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2013 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'On 4 May 2018, Justice Nefi Cordeiro (STJ), at the request of the MPF, ordered the immediate enforcement of the 6-year, 8-month sentence, following the STF''s position on enforcement after the second instance, although appeals were still pending.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El 4 de mayo de 2018, el ministro Nefi Cordeiro (STJ), a petición del MPF, ordenó la ejecución inmediata de la pena de 6 años y 8 meses, siguiendo el criterio del STF sobre ejecución tras la segunda instancia, aunque aún había recursos pendientes.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Representative of the Combralog Consortium, he recorded the February 2002 conversation in which he promised an advantage to Waldomiro; he was convicted in 2012, at first instance, of active corruption and an offence under the Public Procurement Law (8 years'' imprisonment). The defence argued that the clandestine recording was unlawful evidence, a thesis rejected by the judge.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'esquema_waldomiro_diniz' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Representante del Consorcio Combralog, grabó la conversación de febrero de 2002 en la que prometió una ventaja a Waldomiro; fue condenado en 2012, en primera instancia, por cohecho activo y delito de la Ley de Licitaciones (8 años de reclusión). La defensa alegó que la grabación clandestina era prueba ilícita, tesis rechazada por la jueza.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlinhos_cachoeira' AND target = 'esquema_waldomiro_diniz' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
