INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former president of Funcef, he was ordered into temporary custody when the operation was launched in September 2016, and became a defendant in May 2017 in the first Greenfield indictment, with 13 others. Outcome and defence position not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_carlos_caser' AND target = 'esquema_operacao_greenfield' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
