INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Campaign treasurer; he admitted to the CPI that he had run about R$ 12 million in undeclared funds (caixa dois) from Banco Rural loans; his list of transactions gave rise to the investigations. Liability extinguished as time-barred in 2014.', NULL, 'Undeclared funds (caixa dois) stated by the treasurer himself in testimony to the CPI, a figure distinct from the R$ 3.5 million in the indictment', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_claudio_mourao' AND target = 'esquema_mensalao_mineiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Tesorero de la campaña; admitió ante la CPI haber operado una caja B (caixa dois) de unos 12 millones de reales procedentes de préstamos del Banco Rural; su lista de movimientos dio origen a las investigaciones. Responsabilidad penal extinguida por prescripción en 2014.', NULL, 'Caja B (caixa dois) declarada por el propio tesorero en su declaración ante la CPI, cifra distinta de los 3,5 millones de reales de la acusación', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_claudio_mourao' AND target = 'esquema_mensalao_mineiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Together with the businessman Luiz Estevão, he presented to the CPMI, as a legitimate loan, documents for an alleged US$ 4 million Uruguayan financing of the 1989 campaign, the so-called Operation Uruguay (Operação Uruguai). Years later, the Federal Revenue Service concluded that the operation was a sham.', NULL, 'Figure from the Gazeta do Povo; the Correio da Manhã gives US$ 3.75 million. Amount in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_claudio_vieira' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Junto con el empresario Luiz Estevão, presentó a la CPMI, como préstamo legítimo, documentos de una supuesta financiación uruguaya de 4 millones de dólares para la campaña de 1989, la llamada Operación Uruguay. Años después, la Receita Federal (Hacienda) concluyó que la operación fue una farsa.', NULL, 'Cifra de la Gazeta do Povo; el Correio da Manhã cita 3,75 millones de dólares. Importe en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_claudio_vieira' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The president''s private secretary and official treasurer of the 1989 campaign before the Superior Electoral Court (TSE). He told the CPMI that he had not received warnings about PC Farias from Pedro Collor and that he would not take unsubstantiated accusations to the president.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_claudio_vieira' AND target = 'pol_collor' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 1990 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
