INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police in October 2026, with 14 others, over suspected financial fraud in Master''s dealings with BRB; he has been in pre-trial detention since March 2026, and on 11 November 2026 the Prosecutor General''s Office (PGR) told the Supreme Federal Court (STF) he should remain in custody. The defence says the report repeats the same narrative and that no official forensic examination has found any loss to BRB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_daniel_vorcaro' AND target = 'esquema_banco_master_inss' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal en octubre de 2026, junto con otras 14 personas, por sospechas de fraude financiero en las operaciones del Master con el BRB; está en prisión preventiva desde marzo de 2026, y el 11 de noviembre de 2026 la Fiscalía General (PGR) defendió ante el Supremo Tribunal Federal (STF) que siga en prisión. La defensa afirma que el informe repite la misma narrativa y que ninguna pericia oficial ha constatado perjuicio al BRB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_daniel_vorcaro' AND target = 'esquema_banco_master_inss' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
