INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified as head of the scheme alongside his son, he was sentenced at first instance to 3 years and 4 months for active corruption in one of the criminal cases and, on appeal, the sentences were revised (11 years, 1 month and 10 days for active corruption after senility was recognised, which the STJ later removed, according to FolhaMax). In September 2022 Justice Gilmar Mendes (STF) recognised, at the defence''s request, time-barring of the money-laundering offence only.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_darci_vedoin' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado como jefe de la trama junto a su hijo, fue condenado en primera instancia a 3 años y 4 meses por cohecho activo en una de las causas penales y, en segunda instancia, las penas fueron revisadas (11 años, 1 mes y 10 días por cohecho activo tras el reconocimiento de la senilidad, que el STJ retiró después, según FolhaMax). En septiembre de 2022 el ministro Gilmar Mendes (STF) reconoció, a petición de la defensa, la prescripción solo del delito de blanqueo de capitales.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_darci_vedoin' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
