INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A former aide to Flávio Bolsonaro in the Rio de Janeiro state assembly (Alerj), he had atypical transactions of R$ 1.2 million flagged by the financial intelligence unit (Coaf) and was charged by the Rio de Janeiro State Prosecution Service (MP-RJ) as the operator who collected salaries; the indictment was rejected by the Special Body of the Rio de Janeiro Court of Justice (TJ-RJ) on 16 May 2022, at the prosecutors'' request, after the STJ and the STF annulled the evidence, without ruling out a new investigation. The defence denies wrongdoing.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_fabricio_queiroz' AND target = 'esquema_caso_queiroz_rachadinhas' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Exasesor de Flávio Bolsonaro en la Asamblea Legislativa de Río (Alerj), el Coaf (unidad de inteligencia financiera) señaló movimientos atípicos suyos por 1,2 millones de reales y el Ministerio Público de Río de Janeiro (MP-RJ) lo acusó como operador de la recaudación de salarios; el Órgano Especial del Tribunal de Justicia de Río de Janeiro (TJ-RJ) rechazó la acusación el 16 de mayo de 2022, a petición del Ministerio Público, después de que el STJ y el STF anularan las pruebas, sin impedir una nueva investigación. La defensa niega irregularidades.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_fabricio_queiroz' AND target = 'esquema_caso_queiroz_rachadinhas' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
