INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'As Director of International Affairs, he drew up Circular 2,677 of 10 April 1996 and approved the special authorisation that allowed cash deposits of up to R$ 100,000 in CC5 accounts in Foz do Iguaçu; he was governor of the institution from 1997 to 1999.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_gustavo_franco' AND target = 'emp_banco_central' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 1996 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
