INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The CPMI''s final report recommended that he be formally named a suspect for having authorised deposits above the legal limit, creating a loophole for illegal currency remittance; in testimony, he denied complicity, said the decision was backed by the Central Bank''s board and that the Central Bank itself originated the complaints.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_gustavo_franco' AND target = 'esquema_banestado' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El informe final de la CPMI recomendó su imputación por haber autorizado depósitos por encima del límite legal, creando una brecha para la evasión de divisas; en su declaración negó connivencia, afirmó que la decisión contó con el respaldo de la dirección del Banco Central y que fue el propio Banco Central quien originó las denuncias.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_gustavo_franco' AND target = 'esquema_banestado' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
