INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Socio del grupo J&F; según el juez que autorizó la operación, ideó con su hermano la fusión de Florestal y Eldorado y la creación del fondo FIP Florestal, con aportaciones de Funcef y Petros que habrían causado perjuicio a los fondos. Las empresas fueron registradas en septiembre de 2016, y él no fue localizado porque estaba de viaje en Estados Unidos. No se han localizado el desenlace ni la posición de la defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_joesley_batista' AND target = 'esquema_operacao_greenfield' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2016 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
