INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the administrative misconduct case, the 2012 judgment did not accept that the money was an advantage linked to the financing; according to Aos Fatos, the TRF-5 ordered him to pay a fine in 2014, and O Povo lists him among the three ordered to pay a fine. The amount, grounds and any appeal were not found.', NULL, 'Amount of the fine not found in the sources read', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la acción por improbidad, la sentencia de 2012 no reconoció que el dinero fuera una ventaja vinculada a la financiación; según Aos Fatos, el TRF-5 lo condenó a pagar una multa en 2014, y O Povo lo incluye entre los tres condenados a multa. No se localizaron el importe, el fundamento ni un eventual recurso.', NULL, 'Importe de la multa no localizado en las fuentes leídas', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the criminal inquiry, the Federal Court in 2019 rejected the closure requested by the MPF, which cited time-barring of reckless management and influence peddling; on 19 August 2021 it recognised the time-bar and declared extinguished the liability of him and three others involved, without ruling on the merits.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la investigación penal, la Justicia Federal rechazó en 2019 el archivo solicitado por el MPF, que alegaba prescripción de gestión temeraria y tráfico de influencias; el 19 de agosto de 2021 reconoció la prescripción y declaró extinguida la responsabilidad penal de él y de otros tres implicados, sin juicio sobre el fondo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was arrested in the act at Congonhas airport on 8 July 2005, boarding a flight to Fortaleza, with R$ 209,000 in a briefcase and US$ 100,559 strapped to his body, with no proof of origin; the MPF maintains that it was part of a bribe paid by the STN consortium for the BNB financing. The defence claimed the money came from an unidentified friend to open two businesses and has nothing to do with the financing.', 'R$ 209,000 and US$ 100,559', 'Sum of R$ 209,000 in cash and US$ 100,559 converted at the PTAX closing rate of 8/7/2005 (R$ 2.3675), equivalent to R$ 238,073, total R$ 447,073; Congresso em Foco converted US$ 100,000 into about R$ 252,000 and the 2019 decision cites about R$ 600,000 in adjusted values', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'esquema_dolares_na_cueca' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Fue detenido en flagrante en Congonhas el 8 de julio de 2005, al embarcar hacia Fortaleza, con 209.000 reales en un maletín y 100.559 dólares pegados al cuerpo, sin acreditar su origen; el MPF sostiene que formaban parte de un soborno pagado por el consorcio STN por la financiación del BNB. La defensa alegó que el dinero venía de un amigo no identificado para abrir dos negocios y que no tiene nada que ver con la financiación.', 'R$ 209.000 y US$ 100.559', 'Suma de 209.000 reales en efectivo y 100.559 dólares convertidos a la cotización PTAX de cierre del 8/7/2005 (2,3675 reales), equivalentes a 238.073 reales, total de 447.073 reales; Congresso em Foco convirtió 100.000 dólares en unos 252.000 reales y la decisión de 2019 cita unos 600.000 reales en valores corregidos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'esquema_dolares_na_cueca' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was parliamentary aide to the then state deputy José Guimarães, who says he dismissed the aide after the arrest in the act and felt betrayed in the trust he had placed in him.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'pol_jose_guimaraes' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Era asesor parlamentario del entonces diputado estatal José Guimarães, quien afirma haberlo cesado tras la detención en flagrante y haber sido traicionado en la confianza que depositaba en él.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_adalberto_vieira' AND target = 'pol_jose_guimaraes' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
