INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He acted as Raytheon''s commercial representative in Brazil; the company described him as an independent representative with no power to sign contracts on its behalf.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_afonso_assumpcao' AND target = 'emp_raytheon' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
