INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In conversations in September 1995 recorded by the Federal Police, he asked the ambassador to intercede with the presidential palace to unblock the Sivam in the Senate; to the Senate committee, he said that his remark that there was no one left to give money meant that corruption had come to an end.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_afonso_assumpcao' AND target = 'op_julio_cesar_gomes_dos_santos' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
