INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted of passive corruption following charges brought by the Federal Prosecution Service (MPF); jailed in 2014 once the judgment became final. In 2015 the STJ rejected the nullities alleged by the defence and reduced the sentence to 7 years, 9 months and 10 days because of his spontaneous confession.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_carlos_alves_santos' AND target = 'esquema_anoes_orcamento' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
