INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former member of the tax appeals board (Carf), he was arrested in 2015 and convicted at first instance; in April 2020 the 4th Panel of the Federal Regional Court of the 1st Region (TRF-1) unanimously acquitted him of corruption, money laundering and criminal association; in the same ruling, the Panel convicted former Senate director Fernando Mesquita of improperly using his office (advocacia administrativa), with participation attributed to José Ricardo and other defendants. His lawyer said the ruling "showed that the crimes did not occur".', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_ricardo' AND target = 'esquema_operacao_zelotes' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Exconsejero del Carf (tribunal administrativo fiscal), fue detenido en 2015 y condenado en primera instancia; en abril de 2020 la Sala 4.ª del Tribunal Regional Federal de la 1.ª Región (TRF-1) lo absolvió por unanimidad de cohecho, blanqueo de capitales y asociación criminal; en la misma decisión, la Sala condenó al exdirector del Senado Fernando Mesquita por patrocinio de intereses privados ante la Administración (advocacia administrativa), con una participación atribuida a José Ricardo y a otros acusados. Su abogado afirmó que la decisión "señaló que los delitos no ocurrieron".', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_jose_ricardo' AND target = 'esquema_operacao_zelotes' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
