INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He held the post of special adviser to the BNB presidency, to which, according to the MPF, he was appointed through José Guimarães''s influence and from which he allegedly arranged the financing for the STN. In his defence, he said he merely performed institutional liaison and customer-service functions.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'emp_bnb' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Ocupaba el cargo de asesor especial de la presidencia del BNB, adonde, según el MPF, fue designado por influencia de José Guimarães y desde donde habría articulado la financiación al STN. En su defensa, dijo que solo ejercía funciones institucionales de enlace y atención a clientes.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'emp_bnb' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to O Povo, he was one of the three ordered to pay a fine in the administrative misconduct case, alongside Adalberto and Roberto Smith; the 2012 judgment had cleared him for lack of evidence. Aos Fatos places the fine at the TRF-5 in 2014; the amount and grounds were not found.', NULL, 'Amount of the fine not found in the sources read; year 2014 according to Aos Fatos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según O Povo, fue uno de los tres condenados a multa en la acción por improbidad, junto con Adalberto y Roberto Smith; la sentencia de 2012 había descartado su responsabilidad por falta de pruebas. Aos Fatos sitúa la condena a multa en el TRF-5 en 2014; no se localizaron el importe ni el fundamento.', NULL, 'Importe de la multa no localizado en las fuentes leídas; año 2014 según Aos Fatos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The MPF pointed to evidence that the money seized was a bribe for influence peddling in the STN contract, which he allegedly facilitated; the BNB''s internal inquiry (October 2005) concluded that he took part in meetings with consortium executives but found no proof of any improper personal advantage.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El MPF señaló indicios de que el dinero incautado era un soborno por tráfico de influencias en el contrato con el STN, que él habría facilitado; la investigación interna del BNB (octubre de 2005) concluyó que participó en reuniones con directivos del consorcio, pero no obtuvo pruebas de ventaja personal indebida.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the criminal inquiry, the Federal Court in Ceará declared his liability extinguished on 19 August 2021, as time-barred and without ruling on the merits, together with other suspects.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la investigación penal, la Justicia Federal de Ceará declaró extinguida su responsabilidad penal el 19 de agosto de 2021, por prescripción y sin juicio sobre el fondo, junto con otros investigados.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_kennedy_moura_ramos' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Lobbyist arrested and formally named a suspect in 2004; according to the MPF, intercepts caught him saying he had received R$ 15 million from the scheme, and his defence was not found.', NULL, 'Amount stated by Laerte in telephone intercepts, according to the MPF; the Federal Police, according to Folha, attributed about R$ 15 million to Delúbio''s group; not confirmed in any judgment found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_laerte_correa' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Lobista detenido e imputado en 2004; según el MPF, las interceptaciones lo sorprendieron afirmando haber recibido 15 millones de reales de la trama, y no se localizó su defensa.', NULL, 'Importe dicho por Laerte en interceptaciones telefónicas, según el MPF; la Policía Federal, según Folha, atribuyó unos 15 millones de reales al grupo de Delúbio; no confirmado en sentencia localizada', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_laerte_correa' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the testimony of the lobbyist Francisco Honorato to the Federal Police, Laerte had Delúbio''s authorisation to raise funds for the PT in the 2002 campaign; Delúbio says he was introduced to Laerte but never authorised him to speak on his behalf, and Humberto Costa said he knew nothing of this activity.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_laerte_correa' AND target = 'pol_delubio_soares' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la declaración del lobista Francisco Honorato a la Policía Federal, Laerte tenía autorización de Delúbio para recaudar fondos para el PT en la campaña de 2002; Delúbio dice que le presentaron a Laerte pero que nunca lo autorizó a hablar en su nombre, y Humberto Costa dijo desconocer esa actuación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_laerte_correa' AND target = 'pol_delubio_soares' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
