INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former president of Fetranspor, he was convicted at first instance by judge Marcelo Bretas in 2019; in August 2022 the Federal Regional Court of the 2nd Region (TRF-2) annulled all of Bretas''s decisions in the case, including the acceptance of the indictment, and sent the case to the state courts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_lelis_teixeira' AND target = 'esquema_operacao_cadeia_velha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
