INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted in Lava Jato and a cooperating witness, with a plea deal ratified by the STF in 2019. Justice Dias Toffoli annulled his convictions on the basis of the former judge Sergio Moro''s bias, and in February 2025 the STF''s 2nd Panel upheld the annulment by 3 votes to 2, rejecting an appeal by the Prosecutor General''s Office (PGR).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_leo_pinheiro' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
