INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A former Ministry of Education project manager, he was arrested in Operation Acesso Pago in 2022; in January 2024 the government dismissed him after a disciplinary proceeding by the Office of the Comptroller General (CGU) found he had received R$ 20,000 to favour municipalities recommended by the pastors. No criminal outcome found.', NULL, 'Bribe audited by the CGU passed to the former civil servant to favour allied municipalities', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_luciano_musse' AND target = 'esquema_bolsolao_do_mec' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
