INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He confessed and informed on the scheme in a plea agreement, which led to the creation of the CPI; in the main case he was convicted of criminal association, tender fraud and active corruption, but the TRF-1 declared his liability extinguished as time-barred in February 2021 and he obtained judicial pardon in other cases.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_luiz_antonio_vedoin' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
