INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Target of Lava Jato in Curitiba. In May 2024 Justice Dias Toffoli annulled all acts of the 13th Federal Court against him; in September 2024 the STF''s 2nd Panel upheld the nullity but did not order the immediate closure of the cases, which is a matter for the competent courts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_odebrecht' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
