INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In 2020, the Federal Regional Court of the 1st Region (TRF-1) decided that it was not possible to punish him for criminal association and bid fraud in the criminal case under Operation Vampiro, which continues against other defendants under seal; the source does not detail the grounds of the decision.', NULL, 'The source speaks only of the impossibility of punishing him, without detailing the grounds; it is not treated here as an acquittal on the merits', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_pitta' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En 2020, el TRF-1 decidió la imposibilidad de castigarlo por asociación criminal y fraude en licitación en la causa penal de la Operación Vampiro, que sigue contra otros acusados bajo secreto de sumario; la fuente no detalla el fundamento de la decisión.', NULL, 'La fuente habla solo de imposibilidad de castigarlo, sin detallar el fundamento; no se trata aquí como absolución sobre el fondo', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_pitta' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Defendant in an administrative misconduct case before the TRF-1, in which the MPF alleges an agreement to divide up the blood-product market in international tenders and the payment of bribes to the tender committee, and seeks repayment of R$ 27.5 million; he asks for the case to be dismissed, claiming the Federal Police mistranscribed the intercepts.', NULL, 'Repayment to the public purse sought by the MPF, to be paid jointly by all defendants; not an amount ordered', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_pitta' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado en una acción por improbidad administrativa en el TRF-1, en la que el MPF señala un acuerdo de reparto del mercado de hemoderivados en licitaciones internacionales y el pago de sobornos a la comisión de licitación, y reclama un resarcimiento de 27,5 millones de reales; él pide que se desestime, alegando transcripciones equivocadas de las interceptaciones por la Policía Federal.', NULL, 'Resarcimiento al erario reclamado por el MPF, a pagar solidariamente por todos los acusados; no es un importe condenado', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_pitta' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Arrested in February 2007 on accusations of laundering money from frauds against the Ministry of Health; according to the report, he represented foreign laboratories and bribed officials to win tenders, and the Federal Court in São Paulo froze R$ 8.6 million in a UBS account in the name of his brother and mother. The defence is not given in this source; in a later administrative misconduct case, he disputes the transcripts of the intercepts.', NULL, 'Amount frozen by the courts in a relative''s account, not a proven bribe amount; the source cites a shortfall of R$ 120 million between 1997 and 2004 without saying who established it', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_pitta' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2007 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Detenido en febrero de 2007 acusado de blanquear dinero de fraudes contra el Ministerio de Sanidad; según el reportaje, representaba a laboratorios extranjeros y sobornaba a funcionarios para ganar concursos, y la Justicia Federal de São Paulo bloqueó 8,6 millones de reales en una cuenta de UBS a nombre de su hermano y de su madre. La defensa no consta en esta fuente; en una acción posterior por improbidad, impugna las transcripciones de las interceptaciones.', NULL, 'Importe bloqueado judicialmente en una cuenta de familiares, no importe acreditado de soborno; la fuente cita un agujero de 120 millones de reales entre 1997 y 2004 sin indicar quién lo determinó', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcelo_pitta' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2007 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'She was among the group charged by the MP-RJ in the rachadinhas case; on 16/05/2022 the TJ-RJ''s Special Panel rejected the charges against Flávio Bolsonaro, Fabrício Queiroz and 15 others, at the request of the prosecution service itself, after the STJ and the STF annulled the evidence. The decision does not prevent a new investigation.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_marcia_aguiar' AND target = 'esquema_caso_queiroz_rachadinhas' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
