INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A PSL candidate for federal deputy in Pernambuco in 2018, she received R$ 400,000 from the electoral fund and won 274 votes; in June 2022 the Electoral Courts acquitted her, along with other candidates, in the front candidacies (laranjas) case. The decision is subject to appeal.', NULL, 'Funds from the Special Campaign Financing Fund received in Pernambuco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_maria_de_lourdes_paixao' AND target = 'esquema_laranjas_do_psl' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
