INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Appeal court judge (desembargadora) and former president of the TJ-BA, suspended since 2019; on 27 October 2026 the National Council of Justice (CNJ) unanimously imposed the penalty of compulsory availability (disponibilidade), with a proposal for loss of office, which depends on an action by the Office of the Attorney General of the Union (AGU) before the Supreme Federal Court (STF); the STJ had already ordered loss of office in the criminal action.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_maria_do_socorro_santiago' AND target = 'emp_tjba' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Desembargadora y expresidenta del TJ-BA, apartada desde 2019; el 27 de octubre de 2026 el Consejo Nacional de Justicia (CNJ) le impuso, por unanimidad, la pena de disponibilidad, con propuesta de pérdida del cargo, que depende de una acción de la Abogacía General de la Unión (AGU) ante el Supremo Tribunal Federal (STF); el STJ ya había decretado la pérdida del cargo en la acción penal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_maria_do_socorro_santiago' AND target = 'emp_tjba' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Appeal court judge (desembargadora) convicted on 21 October 2026 by the Special Court of the Superior Court of Justice (STJ) and sentenced to 14 years and 11 months in prison, to be served initially in a closed regime, for passive corruption and money laundering; according to the Federal Prosecution Service (MPF), she received bribes, paid through third parties, to favour one party in a land dispute. The defence says there is no sound evidence, that the money was a declared financial transaction between siblings and that it will appeal.', NULL, 'According to the MPF, more than R$ 400,000, paid through third parties; a minimum figure, not the total established.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_maria_do_socorro_santiago' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Desembargadora condenada el 21 de octubre de 2026 por la Corte Especial del Superior Tribunal de Justicia (STJ) a 14 años y 11 meses de prisión, en régimen inicial cerrado, por cohecho pasivo y blanqueo de capitales; según el Ministerio Público Federal (MPF), recibió sobornos, pagados mediante terceros, para favorecer a una de las partes en una disputa de tierras. La defensa afirma que no hay prueba idónea, que el dinero fue una operación financiera declarada entre hermanos y que recurrirá.', NULL, 'Según el MPF, más de 400.000 reales, pagados mediante terceros; es una cifra mínima, no el total determinado.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_maria_do_socorro_santiago' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He obtained authorisation from the 2nd Narcotics Court of the Federal District to tap the ambassador by citing anonymous tips about drug trafficking; the Senate committee saw strong signs that the tap was aimed at the ambassador, and internal inquiries found signs of disciplinary breaches. The police chief maintained that he followed usual procedure.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_mario_jose_oliveira_santos' AND target = 'esquema_sivam' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
