INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted at first instance, he was acquitted in April 2020 by the 4th Panel of the Federal Regional Court of the 1st Region (TRF-1), which found no evidence of corruption, money laundering or criminal association in the alleged sale of provisional measures; in the same ruling, the Panel convicted former Senate director Fernando Mesquita of improperly using his office (advocacia administrativa), with participation attributed to Marcondes and other defendants.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_mauro_marcondes' AND target = 'esquema_operacao_zelotes' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en primera instancia, fue absuelto en abril de 2020 por la Sala 4.ª del Tribunal Regional Federal de la 1.ª Región (TRF-1), que no vio indicios de cohecho, blanqueo de capitales ni asociación criminal en la supuesta venta de medidas provisionales; en la misma decisión, la Sala condenó al exdirector del Senado Fernando Mesquita por patrocinio de intereses privados ante la Administración (advocacia administrativa), con una participación atribuida a Marcondes y a otros acusados.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_mauro_marcondes' AND target = 'esquema_operacao_zelotes' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
