INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Farmer linked to Bom Jesus Agropecuária, convicted on 4 November 2026 by the Special Court of the Superior Court of Justice (STJ) and sentenced to 4 years, 1 month and 20 days in prison for active corruption and money laundering. The defence says that he, like other producers in western Bahia, was a victim of an extortion scheme uncovered by the operation.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_nelson_vigolo' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
