INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to an administrative misconduct (improbidade) lawsuit by the Federal Prosecution Service (MPF), he favoured the companies of Monteiro de Barros and Ferraz in the tender; the TRF-3 upheld the misconduct conviction in 2013. The defence denies any role in diversion of funds.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_nicolau_dos_santos_neto' AND target = 'emp_incal' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
