INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He fled the country after a pre-trial detention order was issued in 1993 and was captured in Thailand. In 1994 he was sentenced by the 10th Federal Court in Brasília to four years for tax evasion, had his habeas corpus petition rejected by the Superior Court of Justice (STJ), and the case ended in 1998 with the extinction of liability on his death.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_pc_farias' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 1993 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Huyó del país tras dictarse su prisión preventiva en 1993 y fue capturado en Tailandia. En 1994 fue condenado por el Juzgado Federal 10.º de Brasilia a cuatro años por evasión fiscal, el Superior Tribunal de Justicia (STJ) denegó su habeas corpus, y el proceso terminó en 1998 con la extinción de la responsabilidad penal por su muerte.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_pc_farias' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 1993 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Unanimously sentenced by the STF to seven years in prison in the semi-open regime, plus a fine, for false statements in documents (falsidade ideológica) linked to the ghost accounts, after confessing that the idea of the accounts had been his. The defence, led by Nabor Bulhões, unsuccessfully asked for confession to be treated as a mitigating factor.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_pc_farias' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 1994 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por unanimidad por el STF a siete años de prisión en régimen semiabierto, más multa, por falsedad documental vinculada a las cuentas fantasma, tras confesar que la idea de las cuentas había sido suya. La defensa, de Nabor Bulhões, pidió sin éxito la atenuante de confesión.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_pc_farias' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 1994 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
