INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former Services Director at Petrobras, convicted in Car Wash cases to sentences totalling more than 39 years; he returned to prison in 2024 and moved to a semi-open regime in 2025. The defence is challenging all acts of the task force and of former judge Sergio Moro. At the Supreme Federal Court (STF), Toffoli and Gilmar Mendes voted to annul the proceedings, Nunes Marques and Mendonça disagreed, and on 10 November 2025 Gilmar asked for the case to be heard in person, suspending the judgment with no date to resume.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_renato_duque' AND target = 'esquema_lava_jato' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2015 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Exdirector de Servicios de Petrobras, condenado en procesos de Lava Jato a penas que suman más de 39 años; volvió a prisión en 2024 y pasó al régimen semiabierto en 2025. La defensa recurre contra todos los actos del grupo de trabajo y del exjuez Sergio Moro. En el Supremo Tribunal Federal (STF), Toffoli y Gilmar Mendes votaron por anular las actuaciones, Nunes Marques y Mendonça discreparon y el 10 de noviembre de 2025 Gilmar pidió llevar el caso a sesión presencial, lo que suspendió el juicio sin fecha para reanudarlo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_renato_duque' AND target = 'esquema_lava_jato' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2015 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
