INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Lawyer convicted on 21 October 2026 by the Special Court of the Superior Court of Justice (STJ) and sentenced to 10 years and 9 months in prison, to be served initially in a closed regime, for active corruption and money laundering; according to the Federal Prosecution Service (MPF), he was among those who arranged the scheme for selling rulings. The sources read record no statement from the defence.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_ricardo_tres' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
