INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He chaired the BNB when the Board approved, in June 2004, the financing to the STN; the MPF described him as negligent and complicit in the irregularities attributed to Kennedy Moura. He and the other executives maintain that the operation was lawful, which the TCU confirmed in December 2005.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_roberto_smith' AND target = 'emp_bnb' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidía el BNB cuando el Directorio aprobó, en junio de 2004, la financiación al STN; el MPF lo señaló como omiso y connivente con las irregularidades atribuidas a Kennedy Moura. Él y los demás directivos sostienen que la operación fue regular, lo que el TCU acreditó en diciembre de 2005.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_roberto_smith' AND target = 'emp_bnb' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Ordered at first instance, on 14 December 2012, to pay a civil fine of R$ 10,000 for breaching the principle of impersonality by approving the rule changes that made the STN financing possible, with the judgment not finding that a bribe was paid. The defence maintained that the operation was lawful, as confirmed by the TCU.', NULL, 'Civil fine set in the judgment of 14/12/2012; final amount and outcome of appeals not found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_roberto_smith' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en primera instancia, el 14 de diciembre de 2012, a una multa civil de 10.000 reales por vulnerar el principio de impersonalidad al aprobar los cambios de reglas que hicieron viable la financiación al STN, sin que la sentencia reconociera pago de soborno. La defensa sostuvo la regularidad de la operación, acreditada por el TCU.', NULL, 'Multa civil fijada en la sentencia del 14/12/2012; importe final y resultado de los recursos no localizados', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_roberto_smith' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A former aide to Marcelo Álvaro Antônio, he was held in temporary custody in 2019 and investigated in the case of the PSL''s front candidacies (laranjas) in Minas Gerais; in June 2026 Justice Gilmar Mendes of the Supreme Federal Court (STF) closed the investigation. The defence position was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_roberto_soares' AND target = 'esquema_laranjas_do_psl' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
