INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to Gtech executives cited in the TRF-1 ruling, in early April 2003 he demanded between R$ 15 million and R$ 20 million, later reduced to R$ 6 million, so as not to block the signing of the contract; Buratti denies having acted as an intermediary.', NULL, 'Last amount demanded according to Gtech executives; the TRF-1 cites at least R$ 10 million and the CPI cited R$ 16 million; no proof of payment', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_rogerio_buratti' AND target = 'emp_gtech' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según directivos de Gtech citados en la sentencia del TRF-1, exigió a principios de abril de 2003 entre 15 y 20 millones de reales, reducidos después a 6 millones, para no impedir la firma del contrato; Buratti niega haber actuado como intermediario.', NULL, 'Último importe exigido según directivos de Gtech; el TRF-1 cita al menos 10 millones de reales y la CPI citó 16 millones; sin prueba de pago', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_rogerio_buratti' AND target = 'emp_gtech' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Acquitted at first instance, he was convicted by the TRF-1 in 2011 of administrative misconduct (improbidade), with a fine of five times Waldomiro''s salary, suspension of political rights and a ban on contracting for five years, for the attempt to have himself imposed as a Gtech consultant. Buratti denied having been an intermediary and is appealing to the STJ.', NULL, 'Amount claimed by the AGU in 2013, with additions, according to Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_rogerio_buratti' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Absuelto en primera instancia, fue condenado por el TRF-1 en 2011 por improbidad, con multa de cinco veces la remuneración de Waldomiro, suspensión de derechos políticos y prohibición de contratar durante cinco años, por el intento de imponerse como consultor de Gtech. Buratti negó haber sido intermediario y recurre al STJ.', NULL, 'Importe reclamado por la AGU en 2013, con recargos, según Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_rogerio_buratti' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
