INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified as the de facto owner of Câmbios Imperial, he was sentenced in December 2008 to nine years and eight months'' imprisonment for fraudulently sending R$ 587 million abroad, with an appeal possible at the time.', NULL, 'Amount sent abroad according to the indictment', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_rubens_catenacci' AND target = 'esquema_banestado' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2008 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
