INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Appeal court judge (desembargadora) of the TJ-BA, suspended since 2020 and compulsorily retired by the National Council of Justice (CNJ), unanimously, in December 2024, in disciplinary proceedings that also confirmed, according to g1, a rachadinha scheme (diversion of staff salaries) in her chambers.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sandra_ines_azevedo' AND target = 'emp_tjba' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
