INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Retired appeal court judge (desembargadora) convicted on 4 November 2026 by the Special Court of the Superior Court of Justice (STJ) and sentenced to 14 years and 20 days in prison, to be served initially in a closed regime, for passive corruption and money laundering, with loss of office; according to the Federal Prosecution Service (MPF), she acted in cases to favour an agribusiness company in exchange for bribes received through her son. The defence argued that the rulings were lawful, that the family''s assets are consistent with declared income and that evidence is void.', NULL, 'A R$ 250,000 bribe that, according to g1, she allegedly received for giving a favourable opinion to a company; the STJ records that the Federal Police seized R$ 250,000 at her and her son''s home. It is not the R$ 2.4 million that, according to the MPF, was paid to the group of defendants.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sandra_ines_azevedo' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Desembargadora jubilada condenada el 4 de noviembre de 2026 por la Corte Especial del Superior Tribunal de Justicia (STJ) a 14 años y 20 días de prisión, en régimen inicial cerrado, por cohecho pasivo y blanqueo de capitales, con pérdida del cargo; según el Ministerio Público Federal (MPF), actuó en procesos para favorecer a una empresa agropecuaria a cambio de sobornos recibidos por medio de su hijo. La defensa alegó que las resoluciones fueron lícitas, que el patrimonio familiar es compatible con los ingresos declarados y que hay nulidad de pruebas.', NULL, 'Soborno de 250.000 reales que, según g1, habría recibido por emitir un dictamen favorable a una empresa; el STJ registra que la Policía Federal incautó 250.000 reales en la casa de ella y de su hijo. No es el total de 2,4 millones de reales que, según el MPF, se habrían pagado al grupo de acusados.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sandra_ines_azevedo' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Mayor''s personal aide identified as the leader of the collection from the bus companies; sentenced at first instance to 15 years, 6 months and 19 days for extortion by a public official (concussão) and passive corruption, he died in 2016 before the appeals were heard, always denying the facts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sergio_gomes_da_silva' AND target = 'esquema_santo_andre' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2001 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
