INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Estaba con el alcalde en la cena previa al secuestro y fue acusado por el MP-SP como inductor del homicidio; el STF anuló la causa penal en 2014, nunca fue juzgado por un jurado y murió en 2016 negando su participación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sergio_gomes_da_silva' AND target = 'pol_celso_daniel' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Retired judge of the TJ-BA; on 27 October 2026 the National Council of Justice (CNJ) unanimously imposed the penalty of compulsory availability (disponibilidade), with a proposal for loss of office, which depends on an action by the Office of the Attorney General of the Union (AGU) before the Supreme Federal Court (STF); the STJ had already ordered loss of office in the criminal action.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sergio_sampaio' AND target = 'emp_tjba' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
