INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Retired judge convicted on 21 October 2026 by the Special Court of the Superior Court of Justice (STJ) and sentenced to 15 years and 8 months in prison, to be served initially in a closed regime, for passive corruption and money laundering; according to the Federal Prosecution Service (MPF), he received bribes, paid through third parties, to favour one party in a land dispute. The defence says he is innocent, that his rulings were lawful and that it will seek to overturn the conviction.', NULL, 'According to the MPF, more than R$ 600,000, paid through third parties; a minimum figure, not the total established.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sergio_sampaio' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Juez jubilado condenado el 21 de octubre de 2026 por la Corte Especial del Superior Tribunal de Justicia (STJ) a 15 años y 8 meses de prisión, en régimen inicial cerrado, por cohecho pasivo y blanqueo de capitales; según el Ministerio Público Federal (MPF), recibió sobornos, pagados mediante terceros, para favorecer a una de las partes en una disputa de tierras. La defensa afirma que es inocente, que sus resoluciones fueron legales y que buscará revertir la condena.', NULL, 'Según el MPF, más de 600.000 reales, pagados mediante terceros; es una cifra mínima, no el total determinado.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_sergio_sampaio' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
