INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Lawyer and son of appeal court judge (desembargadora) Sandra Inês Rusciolelli Azevedo, convicted on 4 November 2026 by the Special Court of the Superior Court of Justice (STJ) and sentenced to 13 years and 11 months in prison, to be served initially in a closed regime, for passive corruption and money laundering; according to the investigation, the money was received through him. The sources read do not show a defence on the merits: at the trial, the Federal Public Defender''s Office (DPU) acted by appointment of the STJ in the absence of the defendants'' lawyers.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_vasco_rusciolelli' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Abogado e hijo de la desembargadora Sandra Inês Rusciolelli Azevedo, condenado el 4 de noviembre de 2026 por la Corte Especial del Superior Tribunal de Justicia (STJ) a 13 años y 11 meses de prisión, en régimen inicial cerrado, por cohecho pasivo y blanqueo de capitales; según la investigación, el dinero se recibía por medio de él. En las fuentes consultadas no consta una defensa de fondo: en el juicio, la Defensoría Pública de la Unión (DPU) actuó por designación del STJ, en ausencia de los abogados de los acusados.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_vasco_rusciolelli' AND target = 'esquema_faroeste' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
