INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted of administrative misconduct (improbidade) for his role in the 2003 meetings with Gtech; in 2011 the TRF-1 raised the fine to 15 times his salary and imposed suspension of political rights and a ban on contracting for five years. Waldomiro claimed he went to the meetings under blackmail and appealed to the STJ.', NULL, 'Amount claimed by the AGU in 2013, with adjustments and fees, according to Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por improbidad administrativa por su actuación en 2003 en las reuniones con Gtech; en 2011 el TRF-1 elevó la multa a 15 veces su remuneración e impuso suspensión de derechos políticos y prohibición de contratar durante cinco años. Waldomiro alegó haber ido a las reuniones bajo chantaje y recurrió al STJ.', NULL, 'Importe reclamado por la AGU en 2013, con actualización y honorarios, según Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In April 2013, the Rio de Janeiro State Court of Justice (TJ-RJ) reduced to 6 years and 8 months'' imprisonment the sentence in the Loterj conviction and acquitted him of the offence of tender fraud.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2013 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En abril de 2013, el Tribunal de Justicia de Río de Janeiro (TJ-RJ) redujo a 6 años y 8 meses de reclusión la pena de la condena de la Loterj y lo absolvió del delito de fraude en la licitación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2013 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'On 4 May 2018, the STJ refused the request for provisional enforcement of Waldomiro''s sentence because an appeal was pending; the later outcome was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El 4 de mayo de 2018, el STJ denegó la solicitud de ejecución provisional de la pena de Waldomiro por haber un recurso pendiente; no se localizó el desenlace posterior.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He testified to the Bingos CPI in August 2005, protected by an STF habeas corpus: he denied having extorted Cachoeira, said he went to the meeting to defend Armando Dile''s interests and admitted passing R$ 100,000 from Cachoeira to the campaign of Geraldo Magela, the PT candidate for governor of the Federal District.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Declaró ante la CPI de los Bingos en agosto de 2005, amparado por un habeas corpus del STF: negó haber extorsionado a Cachoeira, dijo que fue a la reunión para defender los intereses de Armando Dile y admitió haber transferido 100.000 reales de Cachoeira a la campaña de Geraldo Magela, candidato del PT al Gobierno del Distrito Federal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Defendant since January 2011 in a criminal case before the 10th Federal Court in Brasília for extortion by a public official (concussão), fraud (estelionato) and active and passive corruption over the renewal of the Caixa–Gtech contract; according to the indictment, he made the renewal conditional on the hiring of Buratti for more than R$ 10 million. Waldomiro has always denied the accusations.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2011 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado desde enero de 2011 en una causa penal del Juzgado Federal 10.º de Brasilia por concusión, estafa y cohecho activo y pasivo en la renovación del contrato Caixa–Gtech; según la acusación, habría condicionado la renovación a la contratación de Buratti por más de 10 millones de reales. Waldomiro siempre negó las acusaciones.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2011 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the February 2002 recording, he asked Cachoeira for 1% of the contract between the Combralog Consortium and Loterj and for help with election campaigns; he was convicted in 2012, at first instance, of passive corruption and an offence under the Public Procurement Law (12 years'' imprisonment and 3 years'' detention). The defence argued impossible crime, a thesis rejected in the judgment.', NULL, 'Corresponds to 1% of the contract, according to the Rio de Janeiro State Prosecution Service (MP-RJ) indictment; amount requested, with no record of payment in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la grabación de febrero de 2002, solicitó a Cachoeira el 1 % del contrato entre el Consorcio Combralog y la Loterj y ayuda para campañas electorales; fue condenado en 2012, en primera instancia, por cohecho pasivo y delito de la Ley de Licitaciones (12 años de reclusión y 3 de detención). La defensa sostuvo la tesis del delito imposible, rechazada en la sentencia.', NULL, 'Corresponde al 1 % del contrato, según la acusación del MP-RJ; importe solicitado, sin constancia de pago en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_waldomiro_diniz' AND target = 'esquema_waldomiro_diniz' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
