INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Partner in the J&F group; according to the judge who authorised the operation, he devised with his brother the merger of Florestal and Eldorado and the creation of the FIP Florestal fund, with investments from Funcef and Petros that allegedly caused losses to the funds. In September 2016, the companies were searched and he gave a statement to the Federal Police after being compelled to appear. Outcome and defence position not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_wesley_batista' AND target = 'esquema_operacao_greenfield' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2016 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Socio del grupo J&F; según el juez que autorizó la operación, ideó con su hermano la fusión de Florestal y Eldorado y la creación del fondo FIP Florestal, con aportaciones de Funcef y Petros que habrían causado perjuicio a los fondos. En septiembre de 2016, las empresas fueron registradas y él declaró ante la Policía Federal tras ser conducido coercitivamente. No se han localizado el desenlace ni la posición de la defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_wesley_batista' AND target = 'esquema_operacao_greenfield' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2016 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
