INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Propietario y socio controlador de la constructora Gautama, al frente de la articulación empresarial de las obras.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_zuleido_veras' AND target = 'emp_gautama' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 2007 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Owner of Gautama, he was convicted at first instance in the "Sergipe event"; in 2018 the Federal Regional Court of the 5th Region (TRF-5) voted to close the case, accepting the defence argument that the wiretaps used as evidence had been annulled by the Supreme Federal Court (STF), which would lead to the acquittal of all defendants. The Federal Prosecution Service (MPF) appealed to the Superior Court of Justice (STJ), arguing that the ruling was void; the outcome of the appeal was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_zuleido_veras' AND target = 'esquema_operacao_navalha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Dueño de Gautama, fue condenado en primera instancia en el "evento Sergipe"; en 2018 el Tribunal Regional Federal de la 5.ª Región (TRF-5) votó por archivar el proceso, al acoger la tesis de la defensa de que las escuchas telefónicas usadas como prueba habían sido anuladas por el Supremo Tribunal Federal (STF), lo que llevaría a la absolución de todos los acusados. El Ministerio Público Federal (MPF) recurrió al Superior Tribunal de Justicia (STJ) alegando la nulidad de la sentencia; no se ha localizado el desenlace del recurso.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'op_zuleido_veras' AND target = 'esquema_operacao_navalha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
