INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado por el MP-SP como beneficiario de los sobornos recaudados de las empresas de autobuses para financiar campañas y condenado en primera instancia a devolver el importe al erario municipal, de forma solidaria con los demás acusados.', NULL, 'Importe fijado por el Juzgado de Hacienda Pública 1.º de Santo André en mayo de 2016, en una acción por improbidad sujeta a recurso', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'par_pt' AND target = 'esquema_santo_andre' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2001 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the video released by Época, Waldomiro asked Cachoeira for money for PT candidates'' campaigns, as well as a bribe for himself; to the magazine, to the Rio de Janeiro Legislative Assembly and to the Bingos CPI, he said he passed R$ 100,000 to the campaign of Geraldo Magela, the PT candidate for governor of the Federal District, an amount that, according to him, was a donation from Cachoeira, and said he had never been a member of the PT. Cachoeira told the CPI that he allocated nothing to Magela''s campaign, and Magela denied having received any funds and announced a lawsuit for moral damages against Waldomiro. The party is not named as a subject of investigation or a defendant in the sources consulted.', NULL, 'Amount stated by Waldomiro himself to Época and to the Bingos CPI', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'par_pt' AND target = 'esquema_waldomiro_diniz' AND type = 'transaction' AND status = 'confirmed' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En el vídeo divulgado por Época, Waldomiro pedía a Cachoeira dinero para campañas de candidatos del PT, además de un soborno para sí; a la revista, a la Asamblea Legislativa de Río de Janeiro y a la CPI de los Bingos afirmó haber transferido 100.000 reales a la campaña de Geraldo Magela, candidato del PT al Gobierno del Distrito Federal, importe que, según él, fue una donación de Cachoeira, y dijo no haber estado nunca afiliado al PT. Cachoeira dijo a la CPI que no destinó nada a la campaña de Magela, y Magela negó haber recibido fondos y anunció una demanda por daños morales contra Waldomiro. El partido no figura como investigado ni como acusado en las fuentes consultadas.', NULL, 'Importe declarado por el propio Waldomiro a Época y a la CPI de los Bingos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'par_pt' AND target = 'esquema_waldomiro_diniz' AND type = 'transaction' AND status = 'confirmed' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
