INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Recorded asking Joesley Batista for R$ 2 million, he was acquitted of passive corruption in March 2022 by the 7th Federal Criminal Court of São Paulo, which concluded that the conduct described in the indictment "did not exist"; the Federal Regional Court of the 3rd Region (TRF-3) unanimously upheld the acquittal in July 2023. The defence argued that the money was an advance on the sale of a property.', NULL, 'Amount requested in a recording; the courts concluded there was no corruption', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_aecio_neves' AND target = 'esquema_jbs_mala_rocha_loures' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Grabado pidiendo 2 millones de reales a Joesley Batista, fue absuelto de cohecho pasivo en marzo de 2022 por el Juzgado Penal Federal 7.º de São Paulo, que concluyó que la conducta descrita en la acusación "no existió"; el Tribunal Regional Federal de la 3.ª Región (TRF-3) confirmó la absolución por unanimidad en julio de 2023. La defensa sostuvo que el dinero era un anticipo de la venta de un inmueble.', NULL, 'Importe pedido en una grabación; la justicia concluyó que no hubo cohecho', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_aecio_neves' AND target = 'esquema_jbs_mala_rocha_loures' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
