INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The CPMI''s final report recommended that he be formally named a suspect for tax evasion, money laundering, false declaration and concealment of assets; these facts were never tried and he died in 2009.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_celso_pitta' AND target = 'esquema_banestado' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
