INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Afiliado al PMDB de 1980 a 1994, presidió la Comisión Mixta de Presupuesto entre 1988 y 1990.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_cid_carvalho' AND target = 'par_pmdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1988 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was one of the company''s partners; according to the STF, the company was used as an intermediary to give an appearance of donation to funds passed to the campaign.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_clesio_andrade' AND target = 'emp_carbo' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Era uno de los socios de la empresa, utilizada según el STF como intermediaria para dar apariencia de donación a fondos transferidos a la campaña.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_clesio_andrade' AND target = 'emp_carbo' AND type = 'contract' AND status = 'confirmed' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Candidate for deputy governor on Azeredo''s ticket, he appeared as joint guarantor of the loans; sentenced to 5 years, 7 months and 15 days for money laundering, with the entire case annulled by the Minas Gerais Court of Justice (TJMG) in 2019. He denies any wrongdoing and called the conviction unjust.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_clesio_andrade' AND target = 'esquema_mensalao_mineiro' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Candidato a vicegobernador en la candidatura de Azeredo, figuró como deudor solidario de los préstamos; condenado a 5 años, 7 meses y 15 días por blanqueo de capitales, con el proceso íntegramente anulado por el Tribunal de Justicia de Minas Gerais (TJMG) en 2019. Niega irregularidades y calificó la condena de injusta.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_clesio_andrade' AND target = 'esquema_mensalao_mineiro' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Elected senator for Minas Gerais for the party, serving between 2011 and 2014.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_clesio_andrade' AND target = 'par_pmdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2011 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Elegido senador por Minas Gerais por el partido, ejerció el mandato entre 2011 y 2014.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_clesio_andrade' AND target = 'par_pmdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2011 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Tried by the STF in 1994 on a charge of passive corruption linked to the scheme, he was acquitted by 5 votes to 3 for lack of evidence of his involvement.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 1994 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Juzgado por el STF en 1994 por cohecho pasivo vinculado a la trama, fue absuelto por 5 votos a 3 por falta de pruebas de su implicación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 1994 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In Criminal Case 465 (AP 465), a case separate from the 1994 one, the Federal Prosecution Service (MPF) accused him of receiving bribes from advertising companies in exchange for government contracts. The STF acquitted him for insufficient evidence, and three justices considered the passive corruption and false-statement charges time-barred.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la Acción Penal 465 (AP 465), distinta de la de 1994, el MPF lo acusó de recibir sobornos de empresas de publicidad a cambio de contratos del Gobierno. El STF lo absolvió por insuficiencia de pruebas, y tres magistrados consideraron prescritos el cohecho pasivo y la falsedad documental.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Removed from office on 2 October 1992, after the Chamber authorised the proceedings by 441 votes to 38. He resigned on 29 December and, the following day, the Senate barred him from public office for eight years by 76 votes to 2, a result later upheld by the Supreme Federal Court (STF).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Apartado del cargo el 2 de octubre de 1992, después de que la Cámara autorizara el proceso por 441 votos a 38. Dimitió el 29 de diciembre y, al día siguiente, el Senado lo inhabilitó durante ocho años por 76 votos a 2, resultado ratificado después por el Supremo Tribunal Federal (STF).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the CPMI, the president''s personal expenses were paid with money from the scheme, including deposits into the account of his secretary Ana Acioli and a "ghost" cheque used to buy a Fiat Elba. Collor gave a speech denying the statements of the driver Eriberto França and was acquitted by the STF in 1994.', NULL, 'Estimate from the time for 33 months of the term of office, cited in the context of the CPMI report; amount in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la CPMI, los gastos personales del presidente se pagaron con fondos de la trama, incluidos depósitos en la cuenta de la secretaria Ana Acioli y un cheque fantasma utilizado para comprar un Fiat Elba. Collor hizo un pronunciamiento negando las declaraciones del chófer Eriberto França y fue absuelto por el STF en 1994.', NULL, 'Estimación de la época para 33 meses de mandato, citada en el contexto del informe de la CPMI; importe en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'esquema_pc_farias' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 1992 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Elected president for the PRN in 1989 and stayed in the party until 2000, when he joined the PRTB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'par_prn' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1989 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Elegido presidente por el PRN en 1989, permaneció en el partido hasta 2000, cuando se afilió al PRTB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'par_prn' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1989 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the STF conviction, as a former PTB leader he was responsible for political appointments to BR Distribuidora.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'par_ptb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2010 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la condena del STF, como antiguo dirigente del PTB fue responsable de nombramientos políticos en BR Distribuidora.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_collor' AND target = 'par_ptb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2010 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified by Roberto Jefferson as responsible for the payments to legislators, he was convicted of active corruption, sentenced to 6 years and 8 months, and acquitted of conspiracy; some of the defendants argued it was undeclared campaign funds (caixa dois). He received a pardon in March 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado por Roberto Jefferson como responsable de los pagos a parlamentarios, fue condenado por cohecho activo a 6 años y 8 meses y absuelto de asociación ilícita; parte de los acusados sostuvo que se trataba de caja B (caixa dois). Recibió el indulto en marzo de 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former treasurer of the PT, he was convicted of money laundering for allegedly directing the disguising of the loan whose final recipient was said to be the Santo André businessman; the conviction was annulled by the STJ in 2023 because the federal courts lacked jurisdiction and the case was sent to the electoral courts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_santo_andre' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Extesorero del PT, fue condenado por blanqueo de capitales por haber, según la acusación, orientado el encubrimiento del préstamo cuyo destinatario final sería el empresario de Santo André; la condena fue anulada por el STJ en 2023 por incompetencia de la justicia federal y el caso se remitió a la justicia electoral.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_santo_andre' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'His name came up in the case through the testimony of the lobbyist Francisco Honorato; at the time, he stated that the PT had received campaign donations from laboratories, about R$ 1.5 million or R$ 1.6 million, and that everything had been declared in the campaign accounts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Su nombre surgió en el caso por la declaración del lobista Francisco Honorato; en su momento, afirmó que el PT recibió donaciones de campaña de laboratorios, unos 1,5 o 1,6 millones de reales, y que todo estaba declarado en la rendición de cuentas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2004 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police in 2006; according to the report published by Folha, his group would have collected about R$ 15 million, and according to the lobbyist Francisco Honorato, the lobbyist Laerte Correa had his authorisation to raise money for the PT. Delúbio told the Federal Police that he was introduced to Laerte but never authorised him to speak on his behalf and denied having set up a fundraising strategy at the ministry.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal en 2006; según el informe publicado por Folha, su grupo habría alcanzado unos 15 millones de reales, y según el lobista Francisco Honorato, el lobista Laerte Correa tenía su autorización para recaudar para el PT. Delúbio dijo a la Policía Federal que le presentaron a Laerte pero que nunca lo autorizó a hablar en su nombre y negó haber montado una estrategia de recaudación en el ministerio.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged on 25 September 2006 with passive corruption, money laundering and criminal conspiracy, with the indictment accepted on 28 October; the Federal Prosecution Service (MPF) said he was the recipient of part of the bribe, with more than R$ 1 million received according to the intercepts, including an intercepted consignment of R$ 723,000. The defence denies having authorised fundraising at the ministry.', NULL, 'Cash consignment intercepted and destined for Delúbio according to the MPF; the prosecutor spoke of more than R$ 1 million received and the Federal Police, according to Folha, attributed about R$ 15 million to his group; no amount proven in any judgment found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado el 25 de septiembre de 2006 de cohecho pasivo, blanqueo de capitales y asociación ilícita, con acusación admitida el 28 de octubre; el MPF afirmó que era destinatario de parte del soborno, con más de 1 millón de reales recibidos según las interceptaciones, incluido un envío de 723.000 reales interceptado. La defensa niega haber autorizado recaudación en el ministerio.', NULL, 'Envío en efectivo interceptado y destinado a Delúbio según el MPF; el fiscal habló de más de 1 millón de reales recibidos y la Policía Federal, según Folha, atribuyó unos 15 millones de reales a su grupo; ningún importe acreditado en sentencia localizada', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_delubio_soares' AND target = 'esquema_vampiro' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
