INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted in Car Wash cases; in October 2024 Justice Gilmar Mendes annulled all acts of former judge Sergio Moro in two criminal cases against him, extending the finding of Moro''s bias made in Lula''s case.', NULL, 'Bribe attributed by the prosecution; the convictions were annulled', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_dirceu' AND target = 'esquema_lava_jato' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en procesos de Lava Jato; en octubre de 2024 el magistrado Gilmar Mendes anuló todos los actos del exjuez Sergio Moro en dos procesos penales contra él, al extenderle el reconocimiento de la parcialidad de Moro hecho en el caso de Lula.', NULL, 'Soborno atribuido por la acusación; las condenas fueron anuladas', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_dirceu' AND target = 'esquema_lava_jato' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified by the Prosecutor General''s Office (PGR) as head of the political nucleus, he denies the accusations. The STF convicted him of active corruption, sentencing him to 7 years and 11 months, and acquitted him of criminal conspiracy (formação de quadrilha) in 2014; the sentence was extinguished by a pardon in October 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_dirceu' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado por la Fiscalía General (PGR) como jefe del núcleo político, niega las acusaciones. El STF lo condenó por cohecho activo a 7 años y 11 meses y lo absolvió de asociación ilícita (formación de quadrilha) en 2014; la pena se extinguió por indulto en octubre de 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_dirceu' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
