INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the Federal Regional Court of the 2nd Region (TRF-2) in 2019, the decisions in his case were annulled in August 2022, when the TRF-2 sent the case to the state courts because the Federal Courts lacked jurisdiction; in November 2023 the Rio de Janeiro courts closed the administrative misconduct suit against him for lack of evidence.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_edson_albertassi' AND target = 'esquema_operacao_cadeia_velha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por el Tribunal Regional Federal de la 2.ª Región (TRF-2) en 2019, los actos decisorios de su proceso fueron anulados en agosto de 2022, cuando el TRF-2 remitió el caso a la justicia estatal por falta de competencia de la Justicia Federal; en noviembre de 2023 la justicia de Río archivó la acción de improbidad contra él por falta de pruebas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_edson_albertassi' AND target = 'esquema_operacao_cadeia_velha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
