INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Desempeñó el cargo de portavoz del Gobierno y el de diputado estatal por el PMDB de Río de Janeiro.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_edson_albertassi' AND target = 'par_pmdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified by the Federal Prosecution Service (MPF) as the main beneficiary of the diversion of R$ 3.5 million from state-owned companies to his campaign; sentenced to 20 years and 1 month, a sentence reduced by the STJ to 15 years, 7 months and 20 days and then suspended by the STF, which sent the case to the electoral courts. He denies involvement and says he was not responsible for campaign expenses.', NULL, 'Amount of the diversion alleged in the Federal Prosecution Service (MPF) indictment', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_eduardo_azeredo' AND target = 'esquema_mensalao_mineiro' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado por el MPF como principal beneficiario del desvío de 3,5 millones de reales de empresas públicas a su campaña; condenado a 20 años y 1 mes, pena reducida por el STJ a 15 años, 7 meses y 20 días y después suspendida por el STF, que remitió el caso a la justicia electoral. Niega su participación y afirma que no era responsable de los gastos de campaña.', NULL, 'Importe del desvío imputado en la acusación del MPF', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_eduardo_azeredo' AND target = 'esquema_mensalao_mineiro' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
