INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the 13th Federal Court in Curitiba in two cases (the Benin and Sondas cases). The STF''s 2nd Panel annulled both convictions for lack of jurisdiction of the federal courts, given signs of electoral offences, and sent the cases to the electoral courts of Rio de Janeiro; in November 2024 Justice Dias Toffoli rejected the defence''s request to close all the cases, which remain pending. The defence maintains that there was collusion between the former judge Sergio Moro and the task force.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_eduardo_cunha' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por el Juzgado Federal 13.º de Curitiba en dos causas (casos Benin y Sondas). La Segunda Sala del STF anuló ambas condenas por incompetencia de la justicia federal, ante indicios de delitos electorales, y remitió los casos a la justicia electoral de Río de Janeiro; en noviembre de 2024 el ministro Dias Toffoli rechazó la petición de la defensa de cerrar todos los procesos, que siguen en trámite. La defensa sostiene que hubo connivencia entre el exjuez Sergio Moro y el grupo de trabajo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_eduardo_cunha' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
