INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the recordings made public, he was contacted by aides and indicated that he would intercede with Previ; he was not a defendant in the administrative misconduct case over the auction.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_fhc' AND target = 'esquema_grampos_bndes' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según las grabaciones divulgadas, fue contactado por colaboradores e indicó que intercedería ante Previ; no fue acusado en la acción por improbidad sobre la subasta.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_fhc' AND target = 'esquema_grampos_bndes' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'As president, he removed ESCA after a meeting of the National Defence Council on 27 May 1995 and dismissed the ambassador after the scandal; in a letter, he stated that Júlio César never pressed for anything regarding the Sivam.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_fhc' AND target = 'esquema_sivam' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Como presidente, apartó a ESCA tras una reunión del Consejo de Defensa Nacional el 27 de mayo de 1995 y cesó al embajador tras el escándalo; en una carta afirmó que Júlio César nunca ejerció presión alguna sobre el Sivam.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_fhc' AND target = 'esquema_sivam' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'One of the founders of the party in 1988; elected President of the Republic in 1994, took office in 1995 and was re-elected in 1998.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_fhc' AND target = 'par_psdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1988 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Uno de los fundadores del partido en 1988; elegido presidente de la República en 1994, tomó posesión en 1995 y fue reelegido en 1998.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_fhc' AND target = 'par_psdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1988 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged by the Rio de Janeiro State Prosecution Service (MP-RJ) in 2020 with embezzlement (peculato), money laundering and criminal organisation; after the Superior Court of Justice (STJ) and the Supreme Federal Court (STF) annulled evidence and decisions in the case, the Special Body of the Rio de Janeiro Court of Justice (TJ-RJ) rejected the indictment for lack of just cause on 16 May 2022, at the request of the prosecutors themselves, without ruling out a new investigation. In February 2025 Justice Gilmar Mendes rejected MP-RJ appeals to reopen the case. Flávio has always denied the accusations.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_flavio_bolsonaro' AND target = 'esquema_caso_queiroz_rachadinhas' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado por el Ministerio Público de Río de Janeiro (MP-RJ) en 2020 de malversación (peculato), blanqueo de capitales y organización criminal; después de que el Superior Tribunal de Justicia (STJ) y el Supremo Tribunal Federal (STF) anularan pruebas y decisiones del caso, el Órgano Especial del Tribunal de Justicia de Río de Janeiro (TJ-RJ) rechazó la acusación por falta de causa justa el 16 de mayo de 2022, a petición del propio Ministerio Público, sin impedir una nueva investigación. En febrero de 2025 el magistrado Gilmar Mendes rechazó recursos del MP-RJ para reabrir el caso. Flávio siempre ha negado las acusaciones.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_flavio_bolsonaro' AND target = 'esquema_caso_queiroz_rachadinhas' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
