INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged as a member of the political nucleus, he was convicted of active corruption, sentenced to 4 years and 8 months, and acquitted of criminal conspiracy in 2014. The STF extinguished his liability by pardon on 4 March 2015.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_genoino' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
