INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A defendant since 2018, accused of interfering in a tax appeals board (Carf) ruling in favour of Cimentos Penha (a R$ 57.7 million case); in February 2025 the Federal Court in Brasília closed the case as time-barred (prescrição), accepting a defence argument. Time-barring extinguishes liability and is neither an acquittal nor a conviction.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_guido_mantega' AND target = 'esquema_operacao_zelotes' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado desde 2018 de interferir en una resolución del Carf (tribunal administrativo fiscal) a favor de Cimentos Penha (un caso de 57,7 millones de reales); en febrero de 2025 la Justicia Federal de Brasilia cerró el proceso por prescripción, al acoger un argumento de la defensa. La prescripción extingue la responsabilidad penal y no equivale ni a absolución ni a condena.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_guido_mantega' AND target = 'esquema_operacao_zelotes' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
