INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado el 25 de septiembre de 2006 de asociación ilícita (formación de quadrilha) y cohecho pasivo, bajo la acusación de conocer la trama y respaldar a los funcionarios implicados; la defensa lo niega y recuerda que la denuncia inicial al MPF partió de él, y el Tribunal Regional Federal de la 5.ª Región (TRF-5) lo absolvió por unanimidad el 24 de marzo de 2010 por falta de pruebas, después de que el propio MPF pidiera su absolución.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_humberto_costa' AND target = 'esquema_vampiro' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2010 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
