INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Ordered at first instance in 2013 to reimburse the federal government for misappropriating Finam funds intended for the company; in 2019 the TRF-1 overturned the judgment, declaring the reimbursement claim time-barred and finding no proof of an act of misconduct (improbidade). The defence has always denied any link to the Pisoni family.', NULL, 'Amount of the 2013 first-instance judgment, later overturned by the TRF-1', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jader_barbalho' AND target = 'emp_imperador_agroindustrial' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2013 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en primera instancia en 2013 a resarcir a la Unión por la apropiación de fondos del Finam destinados a la empresa; en 2019 el TRF-1 revocó la sentencia, declarando la prescripción del resarcimiento y la falta de prueba del acto de improbidad. La defensa siempre negó cualquier relación con la familia Pisoni.', NULL, 'Importe de la sentencia de primera instancia de 2013, revocada después por el TRF-1', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jader_barbalho' AND target = 'emp_imperador_agroindustrial' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2013 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified in the investigations as the political organiser of the release of Finam projects; he resigned his seat in October 2001, was held for 13 hours in 2002 and has always denied involvement, calling the conclusions of the Ethics Committee a farce.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jader_barbalho' AND target = 'esquema_sudam_sudene' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2001 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado en las investigaciones como articulador político de la liberación de proyectos del Finam; renunció al escaño en octubre de 2001, fue detenido durante 13 horas en 2002 y siempre negó su implicación, calificando de farsa las conclusiones del Consejo de Ética.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jader_barbalho' AND target = 'esquema_sudam_sudene' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2001 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
