INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In March 2025 Justice Alexandre de Moraes closed, at the request of the Prosecutor General''s Office (PGR) and for lack of evidence, the investigation into vaccination card fraud with respect to Bolsonaro. The investigation was closed with no charge and no ruling on the merits.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jair_bolsonaro' AND target = 'esquema_operacao_venire_joias_presidencia' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En marzo de 2025 el magistrado Alexandre de Moraes archivó, a petición de la Fiscalía General (PGR) y por falta de pruebas, la investigación sobre el fraude en la cartilla de vacunación respecto a Bolsonaro. Se archivó la investigación, sin acusación ni juicio sobre el fondo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jair_bolsonaro' AND target = 'esquema_operacao_venire_joias_presidencia' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2025 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police in July 2024 in the inquiry into jewellery received from foreign officials; the defence denies any irregularity.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jair_bolsonaro' AND target = 'esquema_operacao_venire_joias_presidencia' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal en julio de 2024 en la investigación de las joyas recibidas de autoridades extranjeras; la defensa niega irregularidades.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jair_bolsonaro' AND target = 'esquema_operacao_venire_joias_presidencia' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2024 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In March 2026 Prosecutor General Paulo Gonet asked for the investigation into the jewellery to be closed, arguing that the law does not define whether gifts received by presidents belong to the State or to the office-holder. As of November 2026 no Supreme Federal Court (STF) ruling on the request had been located; in July Justice Alexandre de Moraes transferred custody of the jewellery to the Federal Revenue Service for forfeiture proceedings, and in October ordered that Bolsonaro be served notice of a tax-infringement charge. The defence''s position was not found in the sources read.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jair_bolsonaro' AND target = 'esquema_operacao_venire_joias_presidencia' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En marzo de 2026 el fiscal general Paulo Gonet pidió el archivo de la investigación sobre las joyas, al entender que la ley no define si los regalos recibidos por presidentes pertenecen al Estado o al mandatario. Hasta noviembre de 2026 no se localizó decisión del Supremo Tribunal Federal (STF) sobre la petición; en julio el magistrado Alexandre de Moraes transfirió la custodia de las joyas a la Receita Federal (Hacienda) para el procedimiento fiscal de decomiso, y en octubre ordenó notificar a Bolsonaro de un cargo por infracción fiscal. No se localizó la posición de la defensa en las fuentes leídas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jair_bolsonaro' AND target = 'esquema_operacao_venire_joias_presidencia' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
