INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged with passive corruption, criminal association and tender fraud over amendments that benefited Planam, he was unanimously acquitted by the STF''s 1st Panel in December 2014 (AP 521): the rapporteur Rosa Weber considered the offences proven, but found no proof of the deputy''s involvement or of the R$ 15,000 payment alleged by the MPF, and the defence had sought acquittal on the ground that the facts did not exist.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jefferson_campos' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado de cohecho pasivo, asociación criminal y fraude en licitaciones por enmiendas que beneficiaron a Planam, fue absuelto por unanimidad por la Primera Sala del STF en diciembre de 2014 (AP 521): la ponente Rosa Weber consideró probados los delitos, pero no halló prueba de la implicación del diputado ni del pago de 15.000 reales señalado por el MPF, y la defensa había pedido la absolución por inexistencia del hecho.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jefferson_campos' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2014 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
