INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Defendant at the Superior Court of Justice (STJ): its Special Court accepted the Federal Prosecution Service (MPF) indictment against 12 people in the "Sergipe event", including the former governor, and upheld that decision in 2013, rejecting appeals in which his defence argued that the charge did not explain the alleged acts of passive corruption. He died in November 2020; the outcome of the case regarding him was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_alves_filho' AND target = 'esquema_operacao_navalha' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2008 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado ante el Superior Tribunal de Justicia (STJ): su Corte Especial admitió la acusación del Ministerio Público Federal (MPF) contra 12 personas del "evento Sergipe", entre ellas el exgobernador, y mantuvo la decisión en 2013, al rechazar los recursos en los que su defensa alegaba que la acusación no explicaba los supuestos actos de cohecho pasivo. Murió en noviembre de 2020; no se ha localizado el desenlace del caso respecto a él.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_alves_filho' AND target = 'esquema_operacao_navalha' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2008 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
