INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Speaker of the Chamber in 2003, he was convicted of passive corruption and embezzlement (peculato), sentenced to 6 years and 4 months, and acquitted of money laundering on appeal in 2014. The sentence was forgiven by a pardon in March 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_paulo_cunha' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidente de la Cámara en 2003, fue condenado por cohecho pasivo y malversación (peculato) a 6 años y 4 meses y absuelto del blanqueo de capitales en los embargos de 2014. La pena fue perdonada por indulto en marzo de 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_paulo_cunha' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the indictment, the wife of the then Speaker of the Chamber withdrew R$ 50,000 at a Banco Rural branch in 2003 to favour SMP&B; the defence argued it was a transfer from the PT for opinion polls, a thesis accepted by the reviewing judge Lewandowski.', NULL, 'Amount according to the Federal Prosecution Service (MPF) indictment', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_paulo_cunha' AND target = 'esquema_mensalao' AND type = 'transaction' AND status = 'convicted_final' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la acusación, la esposa del entonces presidente de la Cámara retiró 50.000 reales en una sucursal del Banco Rural en 2003 para favorecer a SMP&B; la defensa sostuvo que era una transferencia del PT para encuestas electorales, tesis acogida por el revisor Lewandowski.', NULL, 'Importe según la acusación del MPF', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_paulo_cunha' AND target = 'esquema_mensalao' AND type = 'transaction' AND status = 'convicted_final' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
