INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former PT treasurer, he was one of the first targets of the Curitiba task force, in 2015, and was convicted. In August 2025 Justice Dias Toffoli declared null all Lava Jato acts against him, extending decisions that found collusion between the former judge Sergio Moro and prosecutors. The defence says that Moro''s conduct tainted all the cases.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_vaccari' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2015 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Extesorero del PT, fue uno de los primeros objetivos del grupo de trabajo de Curitiba, en 2015, y llegó a ser condenado. En agosto de 2025 el ministro Dias Toffoli declaró la nulidad de todos los actos de la Lava Jato contra él, extendiendo decisiones que reconocieron connivencia entre el exjuez Sergio Moro y los fiscales. La defensa afirma que la actuación de Moro contaminó todos los procesos.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_vaccari' AND target = 'esquema_lava_jato' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2015 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He became a defendant in May 2017 in the first Greenfield indictment, which charges 14 people with crimes against the financial system, fraudulent and reckless management, money laundering and influence peddling in Funcef investments; according to the indictment, R$ 5.9 million was directed to the PT. Outcome and defence position not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_vaccari' AND target = 'esquema_operacao_greenfield' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Pasó a ser acusado en mayo de 2017 en la primera acusación de Greenfield, que imputa a 14 personas delitos contra el sistema financiero, gestión fraudulenta y temeraria, blanqueo de capitales y tráfico de influencias en inversiones de Funcef; según la acusación, 5,9 millones de reales se destinaron al PT. No se han localizado el desenlace ni la posición de la defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_joao_vaccari' AND target = 'esquema_operacao_greenfield' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
