INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the Federal Regional Court of the 2nd Region (TRF-2) in 2019 of corruption, money laundering and criminal organisation, he died in May 2021; in August 2022 the TRF-2, following a Supreme Federal Court (STF) ruling that the Federal Courts lacked jurisdiction, sent the case to the state courts and annulled all decisions, including the acceptance of the indictment.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jorge_picciani' AND target = 'esquema_operacao_cadeia_velha' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por el Tribunal Regional Federal de la 2.ª Región (TRF-2) en 2019 por cohecho, blanqueo de capitales y organización criminal, murió en mayo de 2021; en agosto de 2022 el TRF-2, siguiendo un criterio del Supremo Tribunal Federal (STF) sobre la falta de competencia de la Justicia Federal, remitió el caso a la justicia estatal y anuló todos los actos decisorios, incluida la admisión de la acusación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jorge_picciani' AND target = 'esquema_operacao_cadeia_velha' AND type = 'process' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
