INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'On 21 June 2012, the 1st Panel of the STJ unanimously decided that he should cease to be a defendant in the administrative misconduct case, holding that a relationship of friendship and political companionship does not support the action; the MPF said it intended to appeal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El 21 de junio de 2012, la Primera Sala del STJ decidió por unanimidad que dejara de ser acusado en la acción por improbidad, al entender que una relación de amistad y compañerismo político no sustenta la acción; el MPF dijo que pretendía recurrir.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was charged by the Federal Prosecution Service (MPF), in December 2005, in the administrative misconduct case as an alleged beneficiary of the BNB contract with the STN consortium, for having recommended Kennedy Moura to the bank. He called the suspicion absurd and said the charge was meant to damage the PT.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Fue acusado por el MPF, en diciembre de 2005, en la acción por improbidad como supuesto beneficiario del contrato del BNB con el consorcio STN, por haber recomendado a Kennedy Moura al banco. Calificó la sospecha de absurda y dijo que la acusación pretende perjudicar al PT.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the criminal inquiry, the Federal Court in Ceará recognised that the offence was time-barred and extinguished his liability on 19 August 2021, without ruling on the merits. The defence says the State did not prove any involvement on his part.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la investigación penal, la Justicia Federal de Ceará reconoció la prescripción y extinguió su responsabilidad penal el 19 de agosto de 2021, sin juicio sobre el fondo. La defensa afirma que el Estado no acreditó ninguna participación suya.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'esquema_dolares_na_cueca' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A member of the PT, he chaired the party''s state branch in Ceará for eight years and was a state deputy at the time of the arrest in the act.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'par_pt' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Afiliado al PT, presidió la dirección estatal del partido en Ceará durante ocho años y era diputado estatal en la época de la detención en flagrante.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_guimaraes' AND target = 'par_pt' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2005 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He has several appellate convictions for administrative misconduct (improbidade administrativa) in civil proceedings linked to the case, including the one upheld in June 2026 by the 6th Civil Panel of the Federal District Court of Justice (TJDFT) in the Call Tecnologia action, which is why the Superior Electoral Court (TSE) upheld, on 24 September 2026, by 5 votes to 2, the rejection of his candidacy for governor of the Federal District for the PSD; on 13 October 2026, however, the TJDFT''s 1st Civil Panel set aside the conviction in another misconduct action (the Uni Repro action) after excluding evidence declared unlawful by the Electoral Courts. The defence argued that he would be eligible after the 2025 change to the Clean Record Law and described the October ruling as fair.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_roberto_arruda' AND target = 'esquema_caixa_pandora' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acumula condenas colegiadas por improbidad administrativa (vía civil) vinculadas al caso, entre ellas la confirmada en junio de 2026 por la 6.ª Sala Civil del Tribunal de Justicia del Distrito Federal (TJDFT) en la acción de Call Tecnologia, por lo que el Tribunal Superior Electoral (TSE) mantuvo, el 24 de septiembre de 2026, por 5 votos a 2, el rechazo de su candidatura al gobierno del Distrito Federal por el PSD; el 13 de octubre de 2026, sin embargo, la 1.ª Sala Civil del TJDFT anuló la condena en otra acción de improbidad (la de Uni Repro) tras excluir pruebas declaradas ilícitas por la Justicia Electoral. La defensa sostuvo que sería elegible tras el cambio de 2025 en la Ley de Ficha Limpia y calificó de justa la decisión de octubre.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_jose_roberto_arruda' AND target = 'esquema_caixa_pandora' AND type = 'process' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
