INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged by the Minas Gerais State Prosecution Service (MP-MG) in 2019 with electoral misrepresentation, misappropriation and criminal association in the case of the PSL''s front candidacies (laranjas) in Minas Gerais; in June 2026 Justice Gilmar Mendes of the Supreme Federal Court (STF) closed the investigation; in a statement, he said the closure was the only possible outcome.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_marcelo_alvaro_antonio' AND target = 'esquema_laranjas_do_psl' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado por el Ministerio Público de Minas Gerais (MP-MG) en 2019 de falsedad ideológica electoral, apropiación indebida y asociación criminal en el caso de las candidaturas de testaferro (laranjas) del PSL en Minas Gerais; en junio de 2026 el magistrado Gilmar Mendes, del Supremo Tribunal Federal (STF), archivó la investigación; en una nota, afirmó que el archivo era el único desenlace posible.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_marcelo_alvaro_antonio' AND target = 'esquema_laranjas_do_psl' AND type = 'transaction' AND status = 'acquitted' AND COALESCE(year, -1) = 2026 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
