INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He became a defendant for passive corruption in the case of the bag containing R$ 500,000 delivered to Rodrigo Rocha Loures, but the Federal Regional Court of the 1st Region (TRF-1) closed the case for lack of evidence in 2021; the Superior Court of Justice (STJ) upheld the decision and, in May 2024, Justice Edson Fachin rejected an appeal by the Federal Prosecution Service (MPF). In a separate obstruction of justice case, he was acquitted in 2019. Temer has always denied the accusations.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_michel_temer' AND target = 'esquema_jbs_mala_rocha_loures' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Pasó a ser acusado de cohecho pasivo en el caso de la maleta con 500.000 reales entregada a Rodrigo Rocha Loures, pero el Tribunal Regional Federal de la 1.ª Región (TRF-1) archivó el proceso por falta de pruebas en 2021; el Superior Tribunal de Justicia (STJ) mantuvo la decisión y, en mayo de 2024, el magistrado Edson Fachin rechazó un recurso del Ministerio Público Federal (MPF). En otro proceso, por obstrucción a la justicia, fue absuelto en 2019. Temer siempre ha negado las acusaciones.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_michel_temer' AND target = 'esquema_jbs_mala_rocha_loures' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
