INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Education Minister recorded saying that, at Bolsonaro''s request, he gave priority to municipalities recommended by pastors; Justice Cármen Lúcia ordered an investigation in March 2022. The defence position does not appear in this source.', NULL, 'Amount of FNDE funds committed or paid soon after meetings with the pastors', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_milton_ribeiro' AND target = 'esquema_bolsolao_do_mec' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Ministro de Educación grabado diciendo que, a petición de Bolsonaro, daba prioridad a municipios indicados por pastores; la magistrada Cármen Lúcia ordenó abrir una investigación en marzo de 2022. La posición de la defensa no consta en esta fuente.', NULL, 'Importe de fondos del FNDE comprometidos o pagados poco después de reuniones con los pastores', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_milton_ribeiro' AND target = 'esquema_bolsolao_do_mec' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Senate Ethics Council on 28 November 2006 rejected Jefferson Péres''s report, which called for his expulsion, and approved by 12 votes to 2 only a verbal warning; he claims innocence and says he dismissed the aide on learning of the allegation.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_ney_suassuna' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El Consejo de Ética del Senado rechazó el 28 de noviembre de 2006 el informe de Jefferson Péres, que pedía la destitución, y aprobó por 12 votos a 2 solo una amonestación verbal; alega inocencia y dice que despidió al asesor al conocer la denuncia.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_ney_suassuna' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Federal Prosecution Service (MPF) in Mato Grosso charged him in October 2008 with criminal conspiracy, passive corruption and money laundering as part of the organisation''s political arm; according to a 2006 report, his former aide Marcelo Carvalho received R$ 225,000 from Planam to submit amendments and said he acted with the senator''s consent, and Suassuna claims innocence.', NULL, 'Amount received by the former aide according to a November 2006 report; the CPI''s list recorded R$ 222,500 for the senator; outcome of the charge not found.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_ney_suassuna' AND target = 'esquema_sanguessugas' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2008 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El MPF de Mato Grosso lo acusó en octubre de 2008 de asociación ilícita, cohecho pasivo y blanqueo de capitales como parte del brazo político de la organización; según un reportaje de 2006, su exasesor Marcelo Carvalho recibió 225.000 reales de Planam para presentar enmiendas y dijo que actuaba con el consentimiento del senador, y Suassuna alega inocencia.', NULL, 'Importe recibido por el exasesor según un reportaje de noviembre de 2006; la lista de la CPI registraba 222.500 reales para el senador; no se localizó el resultado de la acusación.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_ney_suassuna' AND target = 'esquema_sanguessugas' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2008 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Senator and former leader of the PMDB in the Senate in 2006, when he faced proceedings before the Ethics Council.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_ney_suassuna' AND target = 'par_pmdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
