INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The STF (2nd Panel) convicted him in February 2018, sentencing him to 6 years, 10 months and 6 days in the semi-open regime for passive corruption, in a scheme of amendments to buy ambulances; in November 2018 it rejected his second appeal and ordered the sentence to be served, and the defence disputed the length of the sentence.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_nilton_capixaba' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El STF (Segunda Sala) lo condenó en febrero de 2018 a 6 años, 10 meses y 6 días en régimen semiabierto por cohecho pasivo, en una trama de enmiendas para comprar ambulancias; en noviembre de 2018 rechazó su segundo recurso y ordenó el cumplimiento de la pena, y la defensa impugnaba la duración de la pena.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_nilton_capixaba' AND target = 'esquema_sanguessugas' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the CPI''s partial report, he received from Planam the second-largest volume of payments among legislators; his lawyer told the Ethics Council that the money was campaign assistance.', NULL, 'Total attributed by the CPI''s partial report (2006), rounded in amount_brl; it does not necessarily coincide with the facts of the STF conviction.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_nilton_capixaba' AND target = 'esquema_sanguessugas' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
