INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Named by Ronivon in the recording; he denies it, says he voted at the request of Governor Orleir Cameli and was acquitted in the proceedings to strip him of his seat in the Constitution and Justice Committee (CCJ). The Federal Police investigation was closed.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_osmir_lima' AND target = 'esquema_compra_reeleicao' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
