INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'National president of the PSC, he was held in pre-trial detention in Operation Tris in Idem in 2020 and charged by the Federal Prosecution Service (MPF) with arranging the sharing-out of posts and bribes in Rio''s health service. Outcome and defence position not found in an accepted source.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_pastor_everaldo' AND target = 'esquema_operacao_placebo' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidente nacional del PSC, fue detenido preventivamente en la Operación Tris in Idem en 2020 y acusado por el Ministerio Público Federal (MPF) de organizar el reparto de cargos y sobornos en la Sanidad de Río. No se han localizado en una fuente aceptada el desenlace ni la posición de la defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_pastor_everaldo' AND target = 'esquema_operacao_placebo' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2020 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He served as National President of the Social Christian Party (PSC) and organised the party''s political alliances.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_pastor_everaldo' AND target = 'par_psc' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Ejerció como presidente nacional del Partido Social Cristiano (PSC) y articuló las alianzas políticas del partido.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_pastor_everaldo' AND target = 'par_psc' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2018 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The STF''s 1st Panel convicted him on 4 April 2017 of passive corruption and money laundering (12 years'' imprisonment in the closed regime, according to the Prosecutor General''s Office (PGR), which reports that the judgment was certified as final in 2017), on the basis of deposits into the accounts of an aide and his wife and Planam''s cash ledger; the defence argued that the amendments were routine and that there is no proof of receiving money, and Justice Marco Aurélio dissented on the laundering.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_feijo' AND target = 'esquema_sanguessugas' AND type = 'transaction' AND status = 'convicted_final' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La Primera Sala del STF lo condenó el 4 de abril de 2017 por cohecho pasivo y blanqueo de capitales (12 años de reclusión en régimen cerrado, según la PGR, que informa de la firmeza certificada en 2017), con base en depósitos en cuentas de un asesor y de su esposa y en el libro de caja de Planam; la defensa sostuvo que las enmiendas eran rutinarias y que no hay prueba de recepción de dinero, y el ministro Marco Aurélio discrepó en cuanto al blanqueo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_feijo' AND target = 'esquema_sanguessugas' AND type = 'transaction' AND status = 'convicted_final' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Listed as a PSDB deputy for Rio de Janeiro in the CPI''s partial report of 2006; later press reports identify him in the PR.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_feijo' AND target = 'par_psdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2006 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
