INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the Federal Regional Court of the 2nd Region (TRF-2) in 2019, his conviction was annulled by the Supreme Federal Court (STF) in 2022, by 3 votes to 2, because prosecution witnesses were heard after defence witnesses; the case was sent to the state courts, and in November 2023 the Rio de Janeiro courts closed the administrative misconduct suit against him for lack of evidence.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_melo' AND target = 'esquema_operacao_cadeia_velha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por el Tribunal Regional Federal de la 2.ª Región (TRF-2) en 2019, su condena fue anulada por el Supremo Tribunal Federal (STF) en 2022, por 3 votos a 2, porque testigos de la acusación declararon después que los de la defensa; el caso se remitió a la justicia estatal y en noviembre de 2023 la justicia de Río archivó la acción de improbidad contra él por falta de pruebas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_melo' AND target = 'esquema_operacao_cadeia_velha' AND type = 'transaction' AND status = 'annulled' AND COALESCE(year, -1) = 2022 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He served as president of Alerj and in parliamentary seats for the PMDB in Rio de Janeiro.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_melo' AND target = 'par_pmdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
