INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former deputy governor, he was acquitted in an administrative misconduct case for lack of evidence; in March 2023 he was still a defendant in a criminal case for passive corruption and money laundering at the 7th Criminal Court of Brasília, where the defence argues that the civil acquittal should end the proceedings.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_paulo_octavio' AND target = 'esquema_caixa_pandora' AND type = 'process' AND status = 'under_investigation' AND COALESCE(year, -1) = 2023 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
