INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He exposed the scheme in an interview with Folha in 2005 and was convicted of passive corruption and money laundering, sentenced to 7 years and 14 days, with the sentence reduced because he had informed on the case. He received a pardon in March 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_roberto_jefferson' AND target = 'esquema_mensalao' AND type = 'process' AND status = 'convicted_final' AND COALESCE(year, -1) = 2012 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
