INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former chief of staff (Casa Civil) to Mário Covas and member of the São Paulo State Court of Accounts, he was accused by the Federal Prosecution Service (MPF) of receiving bribes from Alstom through an offshore company in Switzerland, according to the prosecution, an inquiry that preceded the one into the train cartel; in December 2021 the 6th Federal Criminal Court of São Paulo declared liability extinguished because the offence was time-barred (prescrição), which is not an acquittal. He remains a defendant in an administrative misconduct suit brought by the São Paulo State Prosecution Service (MP-SP), with no outcome found. The defence position on the merits was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_robson_marinho' AND target = 'esquema_trensalao' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Exjefe de la Casa Civil de Mário Covas y consejero del Tribunal de Cuentas de São Paulo, fue acusado por el Ministerio Público Federal (MPF) de recibir sobornos de Alstom a través de una sociedad offshore en Suiza, según la acusación, investigación que precedió a la del cártel de trenes; en diciembre de 2021 el Juzgado Penal Federal 6.º de São Paulo declaró la extinción de la responsabilidad penal por prescripción, lo que no equivale a una absolución. Sigue acusado en una acción de improbidad del Ministerio Público de São Paulo (MP-SP), sin desenlace localizado. No se ha localizado la posición de la defensa sobre el fondo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_robson_marinho' AND target = 'esquema_trensalao' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2021 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'One of the founders of the PSDB, he was Governor Mário Covas''s chief secretary as head of the Casa Civil from January 1995 to April 1997, before taking up his post at the São Paulo State Court of Accounts (TCE-SP).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_robson_marinho' AND target = 'par_psdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Uno de los fundadores del PSDB, fue el principal secretario del gobernador Mário Covas al frente de la Casa Civil de enero de 1995 a abril de 1997, antes de asumir el cargo en el Tribunal de Cuentas del Estado de São Paulo (TCE-SP).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_robson_marinho' AND target = 'par_psdb' AND type = 'process' AND status = 'confirmed' AND COALESCE(year, -1) = 1995 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Filmed by the Federal Police in 2017 receiving a suitcase with R$ 500,000 from a JBS executive; charged with passive corruption, he became a defendant in the 15th Federal Criminal Court in the Federal District, and the case has been ready for judgment since August 2019, with no judgment found in this review. In testimony, he said he had received the suitcase without knowing its contents and that he did not want to receive it.', NULL, 'Amount in the suitcase handed over in a controlled operation by the Federal Police', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_rodrigo_rocha_loures' AND target = 'esquema_jbs_mala_rocha_loures' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Grabado por la Policía Federal en 2017 recibiendo una maleta con 500.000 reales de un directivo de JBS; acusado de cohecho pasivo, pasó a ser acusado en el Juzgado Federal Criminal 15.º del Distrito Federal, y el proceso estaba listo para sentencia desde agosto de 2019, sin que se haya localizado sentencia en esta revisión. En su declaración afirmó haber recibido la maleta sin saber el contenido y dijo que no quería recibirla.', NULL, 'Importe contenido en la maleta entregada en una acción controlada de la Policía Federal', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_rodrigo_rocha_loures' AND target = 'esquema_jbs_mala_rocha_loures' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2017 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
