INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In a report sent to the Superior Court of Justice (STJ) in 2007, the Federal Police accused him of passive corruption, on suspicion that his aide Ivo Almeida Costa received R$ 100,000 from Gautama; he left the ministry and asserted his "complete and absolute innocence". The outcome of the case regarding him was not found in an accepted source.', NULL, 'Amount the aide allegedly received from Gautama, according to the Federal Police; not an amount recognised in a court decision', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_silas_rondeau' AND target = 'esquema_operacao_navalha' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2007 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En un informe enviado al Superior Tribunal de Justicia (STJ) en 2007, la Policía Federal lo acusó de cohecho pasivo, por la sospecha de que su asesor Ivo Almeida Costa recibió 100.000 reales de Gautama; dejó el ministerio y afirmó su "completa y absoluta inocencia". No se ha localizado en una fuente aceptada el desenlace del caso respecto a él.', NULL, 'Importe que, según la Policía Federal, habría recibido el asesor de Gautama; no es un importe reconocido en una resolución judicial', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_silas_rondeau' AND target = 'esquema_operacao_navalha' AND type = 'transaction' AND status = 'under_investigation' AND COALESCE(year, -1) = 2007 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
