INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the STF, he received R$ 8.8 million in 2003 and 2004 to vote in favour of government bills, laundered through the company Garanhuns; Conjur reported R$ 10 million passed on by the PT through Delúbio Soares.', NULL, 'Amount attributed by the STF according to Exame; Conjur reported R$ 10 million', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_valdemar_costa_neto' AND target = 'esquema_mensalao' AND type = 'transaction' AND status = 'convicted_final' AND COALESCE(year, -1) = 2003 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
