INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Sentenced at first instance in January 2015 to five years and five months for illegal currency remittance and clandestine holding of deposits abroad, in a case arising from Operation Farol da Colina, an offshoot of the Banestado case; the Federal Prosecution Service (MPF) appealed to increase the sentence.', NULL, 'Value of the 2002 transactions according to the Federal Prosecution Service (MPF), equivalent to about R$ 3.8 million in adjusted values; amount in US dollars, with no direct conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_vittorio_medioli' AND target = 'esquema_banestado' AND type = 'transaction' AND status = 'convicted_appealing' AND COALESCE(year, -1) = 2002 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
