INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Named in Ronivon Santiago''s recording as an alleged recipient, she was acquitted in 1998 in the proceedings for breach of parliamentary decorum before the Chamber of Deputies'' Constitution and Justice Committee (CCJ). Before the CCJ, she denied receiving money and described the recordings as false and slanderous.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_zila_bezerra' AND target = 'esquema_compra_reeleicao' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Citada en la grabación de Ronivon Santiago como supuesta beneficiaria, fue absuelta en 1998 en el procedimiento por quiebra del decoro parlamentario ante la Comisión de Constitución y Justicia (CCJ) de la Cámara de los Diputados. Ante la CCJ, negó haber recibido dinero y calificó las grabaciones de falsas y calumniosas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE source = 'pol_zila_bezerra' AND target = 'esquema_compra_reeleicao' AND type = 'process' AND status = 'acquitted' AND COALESCE(year, -1) = 1998 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
